insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('seeschdodt', 'Seeschdodt', '', '', '', '', 'Seestadt', '[{"kategorie": "wörtlich, kurz für", "text": "\"Seestadt Aspern\" = \"eines der größten und ambitioniertesten Stadtentwicklungsprojekte in Europa\""}, {"kategorie": "", "text": "Es befindet sich im 22. Wiener Gemeindebezirk ([[Donaustadt]]), im nordöstlichen Teil von Wien, wird auf dem Gelände des ehemaligen Flugfelds Aspern entwickelt und soll bis zur Fertigstellung Platz für etwa 20.000 Bewohner und 20.000 Arbeitsplätze bieten"}, {"kategorie": "", "text": "Die Idee zur Entwicklung der Seestadt Aspern entstand in den frühen 2000er Jahren als Teil der langfristigen Stadtentwicklungspläne Wiens, um neuen Wohnraum zu schaffen und den Stadtteil Donaustadt weiter auszubauen. Die offizielle Planung begann 2004, und der Bau startete 2009. Das gesamte Projekt soll bis in die 2030er Jahre andauern"}, {"kategorie": "", "text": "Das Herzstück der Seestadt Aspern ist ein großer künstlicher See, um den sich die Wohn- und Bürogebäude gruppieren. Die Stadtplanung sieht eine Mischung aus Wohnhäusern, Büros, Bildungseinrichtungen, Geschäften und Freizeiteinrichtungen vor, um eine lebendige, gemischt genutzte Nachbarschaft zu schaffen. Die Architektur in der Seestadt ist modern und innovativ, mit einem starken Fokus auf Nachhaltigkeit und Energieeffizienz."}, {"kategorie": "", "text": "Die Seestadt Aspern ist in verschiedene Quartiere unterteilt, von denen jedes einen eigenen Charakter und Schwerpunkt hat. Es gibt großzügige Grünflächen, Parks und Spielplätze, die zur hohen Lebensqualität beitragen sollen."}]'::jsonb, ''),
  ('schdodtbaun', 'Schdodtbaun', '', '', '', '', 'Stadtbahn', '[{"kategorie": "wörtlich, kurz für", "text": "\"Wiener Stadtbahn\" = \"ehemaliges Nahverkehrssystem in Wien, das Ende des 19. Jahrhunderts entwickelt wurde und die Grundlage für das heutige Wiener U-Bahn- und S-Bahn-System bildet\""}, {"kategorie": "", "text": "Die Wiener Stadtbahn wurde zwischen 1898 und 1901 eröffnet und war ein bedeutendes Infrastrukturprojekt der [[Habsburgermonarchie]]. Sie umfasste mehrere Linien, die die Stadt mit ihren Vororten verbanden und sowohl für den Personen- als auch für den Güterverkehr genutzt wurden"}, {"kategorie": "", "text": "Das Netz der Wiener Stadtbahn bestand aus vier Hauptstrecken, die radial um das Zentrum Wiens verliefen und die Stadtteile mit dem Stadtzentrum verbanden. Die wichtigsten Strecken waren:  (i) Wienflusslinie (heute Teil der U4): Diese Linie folgte dem Verlauf des [[Wienflusses]] und verband die westlichen Stadtteile, darunter [[Hütteldorf]], mit dem Stadtzentrum und endete in [[Heiligenstadt]];  (ii) Gürtellinie (heute Teil der U6): Diese Linie verlief entlang des [[Gürtels]], einer Ringstraße um das Zentrum Wiens, und verband die nördlichen und südlichen Bezirke miteinander;  (iii) Donaukanallinie: Diese Linie verlief entlang des [[Donaukanals]] und verband die östlichen Stadtteile mit dem zentralen Bereich Wiens;  (iv) [[Vorortelinie]] (heute Teil der S45): Diese Linie verband die Vororte Wiens und verlief in einem Bogen von Nordwesten nach Südosten durch die Außenbezirke"}, {"kategorie": "", "text": "Die Planung und der Bau der Stadtbahn wurden von bedeutenden Persönlichkeiten wie dem Architekten Otto Wagner, dem Ingenieur Wilhelm von Engerth und dem Stadtplaner und Politiker Karl Ritter von Ghega vorangetrieben"}, {"kategorie": "", "text": "Die Stadtbahn wurde zwischen 1898 und 1901 eröffnet und war von Anfang an sowohl für den Personen- als auch für den Güterverkehr ausgelegt. Sie wurde zunächst von Dampflokomotiven befahren, was sie von den später elektrifizierten Systemen unterschied"}, {"kategorie": "", "text": "Die Bahnhöfe der Stadtbahn, darunter berühmte Stationen wie [[Karlsplatz]], [[Gumpendorfer]] Straße und [[Schönbrunn]], zeichnen sich durch ihre elegante Gestaltung und die Verwendung moderner Materialien wie Glas und Eisen aus. Viele dieser Gebäude sind bis heute erhalten und stehen unter Denkmalschutz"}, {"kategorie": "", "text": "Die Stadtbahn umfasst auch zahlreiche Viadukte und Brücken, die über Straßen und Flüsse führten. Diese Bauwerke sind nicht nur funktional, sondern auch architektonisch beeindruckend und tragen zur charakteristischen Stadtsilhouette Wiens bei"}]'::jsonb, ''),
  ('schdodtbaunbeegn', 'Schdodtbaunbeegn', '', '', '', '', 'Stadtbahnbögen', '[{"kategorie": "allg.", "text": "\"eine Reihe von Viaduktbögen, die ursprünglich als Teil der [[Wiener]] Stadtbahn im späten 19. Jahrhundert errichtet wurden\""}, {"kategorie": "", "text": "Diese Bögen, die sich hauptsächlich entlang der Gürtellinie und der Wienflusslinie erstrecken, gehören zu den markanten architektonischen Merkmalen des Wiener Stadtbildes. Sie wurden von Otto Wagner, einem führenden Architekten des Jugendstils, entworfen und haben sich im Laufe der Zeit von rein funktionalen Eisenbahnstrukturen zu multifunktionalen städtischen Räumen entwickelt"}, {"kategorie": "", "text": "Die Stadtbahnbögen wurden zwischen 1894 und 1901 als Teil des Wiener Stadtbahnprojekts aus Ziegeln und Eisen erbaut und dienten ursprünglich als Viadukte, über die die Stadtbahnzüge fuhren. Unter den Bögen verliefen Straßen oder Flussläufe, oder sie boten Raum für Lager und Werkstätten"}, {"kategorie": "", "text": "In den vergangenen Jahrzehnten wurden viele der Stadtbahnbögen saniert und umgenutzt. Heute beherbergen sie eine Vielzahl von Restaurants, Bars, Clubs und Cafés, die besonders bei jungen Menschen und Nachtschwärmern beliebt sind. Diese Lokale nutzen den charakteristischen Raum unter den Bögen und tragen zu einer lebendigen Kulturszene in Wien bei"}]'::jsonb, ''),
  ('schdefansplotz', 'Schdefansplotz', '', '', '', '', 'Stephansplatz', '[{"kategorie": "allg.", "text": "einer der bekanntesten und zentralsten Plätze in Wien, gelegen im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Der Platz ist nach dem [[Stephansdom]] benannt, dem imposanten gotischen Wahrzeichen der Stadt, das sich im Herzen des Platzes erhebt. Der Stephansplatz ist nicht nur ein historisches und kulturelles Zentrum Wiens, sondern auch ein bedeutender Verkehrsknotenpunkt und ein beliebter Treffpunkt für Einheimische und Touristen"}, {"kategorie": "", "text": "Der Stephansplatz entstand im Mittelalter als Vorplatz des Stephansdoms, der ursprünglich eine kleinere romanische Kirche war, bevor er im gotischen Stil erweitert wurde. Der Platz diente als Marktplatz und zentraler Versammlungsort für die Bürger Wiens"}, {"kategorie": "", "text": "Im 17. und 18. Jahrhundert, während der Barockzeit, wurde der Stephansplatz weiter ausgebaut und erhielt seine heutige Struktur. Im 19. Jahrhundert wurde der Platz modernisiert und zunehmend zum Mittelpunkt des gesellschaftlichen Lebens in Wien"}, {"kategorie": "", "text": "Nach dem Zweiten Weltkrieg und den Zerstörungen in der Stadt wurde der Stephansplatz schrittweise wieder aufgebaut und modernisiert. Rund um den Stephansplatz finden sich auch moderne Gebäude, darunter das [[Haas-Haus]], ein postmodernes Bauwerk aus den 1990er Jahren, das wegen seiner Glasfassade und seiner zeitgenössischen Architektur auffällt. Das Haas-Haus steht im architektonischen Kontrast zum historischen Stephansdom und spiegelt den Wandel der Stadt wider."}]'::jsonb, ''),
  ('schdrossnbaun', 'Schdrossnbaun', '', '', '', '', 'Straßenbahn', '[{"kategorie": "wörtlich, kurz für", "text": "\"Wiener Straßenbahn\" = \"eines der ältesten und umfangreichsten Straßenbahnsysteme der Welt und ein zentraler Bestandteil des öffentlichen Nahverkehrs in Wien, umgangssprachlich auch [[Bim]] genannt\""}, {"kategorie": "", "text": "Sie wird von den [[Wiener]] Linien betrieben und verbindet fast alle Bezirke der Stadt miteinander"}, {"kategorie": "", "text": "Das Wiener Straßenbahnnetz ist eines der größten in Europa und umfasst über 170 Kilometer Streckenlänge mit mehr als 30 Linien. Es erstreckt sich über fast das gesamte Stadtgebiet und verbindet die meisten Bezirke Wiens miteinander"}, {"kategorie": "", "text": "Eine der bekanntesten Strecken ist die Ringstraße, die um die Innere Stadt führt und wichtige Sehenswürdigkeiten wie die Staatsoper, das Rathaus und das Parlament passiert. Die Straßenbahnen auf dieser Strecke bieten nicht nur eine praktische Verbindung, sondern auch eine eindrucksvolle Stadtrundfahrt."}]'::jsonb, ''),
  ('hgm', 'HGM', '', '', '', '', 'HGM', '[{"kategorie": "wörtlich, Abkürzung für", "text": "\"Heeresgeschichtliches Museum\" =  \"ältestes und bedeutendstes Militärmuseum Österreichs\""}, {"kategorie": "", "text": "Es befindet sich im historischen [[Wiener]] Arsenal im 3. Wiener Gemeindebezirk ([[Landstraße]]) und widmet sich der Darstellung der österreichischen Militärgeschichte vom späten Mittelalter bis in die Gegenwart. Das Museum beherbergt eine beeindruckende Sammlung von Exponaten, die die militärische Geschichte und Entwicklung Österreichs über mehrere Jahrhunderte hinweg dokumentieren"}, {"kategorie": "", "text": "Das Heeresgeschichtliche Museum wurde in der Mitte des 19. Jahrhunderts auf Initiative von Kaiser Franz Joseph I. errichtet, um die militärischen Errungenschaften und die Geschichte der [[Habsburgermonarchie]] zu dokumentieren"}, {"kategorie": "", "text": "Der Bau des Museums begann 1850 als Teil des Wiener Arsenals und wurde 1856 abgeschlossen. Es war von Anfang an als zentrale Sammlung und Ausstellungsstätte für die militärische Geschichte des österreichischen Kaiserreichs konzipiert. Die offizielle Eröffnung fand 1891 statt, wobei das Museum damals noch als \"Kaiserlich-Königliches Hofwaffenmuseum\" bekannt war"}, {"kategorie": "", "text": "Das Gebäude des Heeresgeschichtlichen Museums ist ein herausragendes Beispiel für den [[Historismus]], entworfen von dem Architekten Ludwig Förster. Es zeigt Elemente der Neorenaissance und Neugotik und ist reich verziert, insbesondere im Eingangsbereich, der von Statuen und Reliefs berühmter österreichischer Militärführer geprägt ist. Der Innenraum ist ebenso imposant, mit großen Ausstellungshallen und prächtigen Sälen"}, {"kategorie": "", "text": "Das Heeresgeschichtliche Museum beherbergt eine der bedeutendsten Sammlungen zur Militärgeschichte in Europa. Die Exponate decken verschiedene Epochen ab, von den Türkenkriegen im 16. und 17. Jahrhundert, über die napoleonischen Kriege bis zu den beiden Weltkriegen und den jüngsten militärischen Einsätzen Österreichs"}, {"kategorie": "", "text": "Besonderes Highlight ist das Automobil, in dem [[Erzherzog]] Franz Ferdinand und seine Frau Sophie am 28. Juni 1914 in Sarajevo ermordet wurden, was den Ersten Weltkrieg auslöste."}]'::jsonb, ''),
  ('schduwaviatl', 'Schduwaviatl', '', '', '', '', 'Stuwerviertel', '[{"kategorie": "allg.", "text": "\"Stadtteil im 2. Wiener Gemeindebezirk ([[Leopoldstadt]])\""}, {"kategorie": "", "text": "Es liegt nordöstlich des Stadtzentrums und wird durch den [[Praterstern]] im Westen, die [[Ausstellungsstraße]] im Süden, den [[Donaukanal]] im Osten und die [[Messe]] Wien im Norden begrenzt"}, {"kategorie": "", "text": "Ursprünglich war ein Teil des heutigen Stuwerviertels aufgrund seiner Lage an der damals noch unregulierten Donau Augebiet mit Wiesen, Waldstücken und häufigen Überschwemmungen. 1766 öffnete [[Kaiser]] Joseph II. den bis dahin dem Kaiserhof vorbehaltenen [[Wiener]] Prater für die Öffentlichkeit. Teilweise auf dem Gebiet des heutigen Stuwerviertels entstand dann der [[Wurstelprater]] oder [[Volksprater]] als Vergnügungspark. Seinen Namen erhielt das Viertel (erst in den letzten Jahrzehnten des 20. Jahrhunderts) von Johann Georg Stuwer, der in dieser Gegend ab 1774 populäre Kunstfeuerwerke veranstaltete. 1876 wurde von seinem Urenkel Anton Stuwer das letzte Stuwersche Feuerwerk abgebrannt; 1898 wurde hier die Stuwerstraße benannt"}, {"kategorie": "", "text": "Bedingt durch die Nachbarschaft mit Europas größtem Vergnügungspark, entstand Anfang des 20. Jahrhunderts eine Rotlichtszene, die sich zu einer der größten Wiens entwickelt hat. Es gibt Zimmervermietungen für Straßenprostituierte, Bars, Bordelle und Sexshops. Das Stuwerviertel wurde im öffentlichen Bewusstsein daher immer wieder mit Fragen zu Sicherheit und Ordnung in Verbindung gebracht. Seit 2011 ist in Wien die Straßenprostitution in Wohngebieten, also auch im Stuwerviertel, offiziell verboten"}, {"kategorie": "", "text": "Heute ist das Stuwerviertel ein lebendiges und vielfältiges Stadtviertel, das sowohl von seiner Nähe zum Prater als auch von seiner zentralen Lage profitiert. Es ist geprägt von einer Mischung aus Altbauten, die aus der [[Gründerzeit]] stammen, und modernen Wohn- und Bürogebäuden."}]'::jsonb, ''),
  ('ausschdoellungsschdrossn', 'Ausschdöllungsschdrossn', '', '', '', '', 'Ausstellungsstraße', '[{"kategorie": "allg.", "text": "\"bedeutende Straße im 2. Wiener Gemeindebezirk ([[Leopoldstadt]])\""}, {"kategorie": "", "text": "Sie verläuft entlang des [[Wiener]] Praters und verbindet den [[Praterstern]], einen zentralen Verkehrsknotenpunkt, mit der [[Messe]] Wien und dem [[Ernst-Happel-Stadion]]"}, {"kategorie": "", "text": "Die Ausstellungsstraße wurde im späten 19. Jahrhundert angelegt, als Wien begann, sich als internationaler Messestandort zu etablieren. Die Straße war von Anfang an eng mit dem Messe- und Ausstellungswesen verbunden, was auch ihren Namen erklärt"}, {"kategorie": "", "text": "Die Ausstellungsstraße ist geprägt von einer Mischung aus historischen und modernen Gebäuden. Ihre Umgebung umfasst sowohl städtische Wohngebiete als auch große Veranstaltungsorte und Grünflächen."}]'::jsonb, ''),
  ('lassalleschdrossn', 'Lassalleschdrossn', '', '', '', '', 'Lassallestraße', '[{"kategorie": "allg.", "text": "wichtige Verkehrsstraße im 2. Wiener Gemeindebezirk ([[Leopoldstadt]])"}, {"kategorie": "", "text": "Sie verläuft in Nord-Süd-Richtung und verbindet den [[Praterstern]], einen zentralen Verkehrsknotenpunkt, mit der [[Reichsbrücke]] und der [[Donau]], wo sie in die [[Wagramer]] Straße übergeht"}, {"kategorie": "", "text": "Die Lassallestraße ist benannt nach Ferdinand Lassalle, einem deutschen Sozialisten und Mitbegründer der Arbeiterbewegung"}, {"kategorie": "", "text": "Mit ihrer Mischung aus Wohngebäuden, Büros und öffentlichen Einrichtungen sowie ihrer hervorragenden Anbindung an das öffentliche Verkehrsnetz ist die Lassallestraße ein bedeutender Teil des städtischen Lebens in Wien."}]'::jsonb, ''),
  ('noadbaunviatl', 'Noadbaunviatl', '', '', '', '', 'Nordbahnviertel', '[{"kategorie": "allg.", "text": "\"modernes Stadtentwicklungsgebiet im 2. Wiener Gemeindebezirk ([[Leopoldstadt]])\""}, {"kategorie": "", "text": "Es entsteht auf dem ehemaligen Gelände des [[Nordbahnhofs]], einem historischen Bahngelände, das lange Zeit ungenutzt blieb. Das Nordbahnviertel ist eines der größten innerstädtischen Entwicklungsprojekte Wiens und wird in den kommenden Jahren zu einem lebendigen, urbanen Viertel mit Wohn- und Bürogebäuden, Schulen, Parks und sozialen Einrichtungen ausgebaut"}, {"kategorie": "", "text": "Das Nordbahnviertel liegt im nordwestlichen Teil der Leopoldstadt, in der Nähe des [[Pratersterns]] und des [[Augartens]]. Es wird im Westen von der [[Nordbahnstraße]] und im Osten von der Walcherstraße sowie dem [[Handelskai]] begrenzt. Das Viertel erstreckt sich über eine Fläche von etwa 85 Hektar und ist gut an das öffentliche Verkehrsnetz Wiens angebunden."}]'::jsonb, ''),
  ('noadbaunhof', 'Noadbaunhof', '', '', '', '', 'Nordbahnhof', '[{"kategorie": "allg.", "text": "\"historischer Bahnhof im 2. Wiener Gemeindebezirk ([[Leopoldstadt]])\""}, {"kategorie": "", "text": "Der Nordbahnhof war einer der bedeutendsten Bahnhöfe in Wien und diente als zentraler Verkehrsknotenpunkt für den Eisenbahnverkehr in den nördlichen Teil der [[Habsburgermonarchie]]. Er spielte eine wesentliche Rolle im Personen- und Güterverkehr zwischen Wien und den nördlichen Regionen, einschließlich Böhmen, Mähren und Galizien"}, {"kategorie": "", "text": "Der Nordbahnhof wurde 1838 als Endstation der Nordbahn eröffnet, der ersten Dampfeisenbahn Österreichs und der gesamten Habsburgermonarchie. Die Nordbahn war eine wichtige Verkehrsverbindung von Wien nach Böhmen und weiter nach Galizien"}, {"kategorie": "", "text": "Nach dem Zweiten Weltkrieg begann der Niedergang des Nordbahnhofs. Mit der Veränderung der politischen und wirtschaftlichen Verhältnisse und der zunehmenden Bedeutung anderer Verkehrswege verlor der Bahnhof an Bedeutung. In den 1970er Jahren wurde der Personenverkehr eingestellt, und der Nordbahnhof wurde zunehmend vernachlässigt. Die Bahnhofsgebäude verfielen, und das Gelände wurde schließlich größtenteils aufgegeben"}, {"kategorie": "", "text": "Das Gelände des ehemaligen Nordbahnhofs wird heute im Rahmen eines umfassenden Stadtentwicklungsprojekts umgestaltet. Das [[Nordbahnviertel]] entsteht auf dem ehemaligen Bahngelände und wird zu einem modernen, urbanen Stadtviertel mit Wohn- und Bürogebäuden, Parks und sozialer Infrastruktur ausgebaut. Dieses Projekt steht exemplarisch für die Umnutzung ehemaliger Industrie- und Bahngelände in lebenswerte Stadtquartiere."}]'::jsonb, ''),
  ('noadbaunschdrossn', 'Noadbaunschdrossn', '', '', '', '', 'Nordbahnstraße', '[{"kategorie": "allg.", "text": "bedeutende Verkehrsstraße im 2. Wiener Gemeindebezirk ([[Leopoldstadt]])"}, {"kategorie": "", "text": "Sie verläuft in Nord-Süd-Richtung und verbindet das Stadtzentrum mit dem Nordbahnhof-Gelände und den nördlichen Teilen des Bezirks. Die Straße ist nach der Nordbahn benannt, der ersten Dampfeisenbahn der [[Habsburgermonarchie]], deren Endstation der historische [[Nordbahnhof]] war"}, {"kategorie": "", "text": "Mit dem Niedergang des Nordbahnhofs in der zweiten Hälfte des 20. Jahrhunderts und der Verlagerung des Verkehrs in andere Bereiche Wiens verlor die Nordbahnstraße etwas von ihrer ursprünglichen Funktion als Hauptzugangsstraße zum Bahnhof. Dennoch blieb sie eine wichtige Verkehrsstraße im 2. Bezirk, die sowohl Wohngebiete als auch Gewerbegebiete bedient."}]'::jsonb, ''),
  ('haundlskej', 'Haundlskej', '', '', '', '', 'Handelskai', '[{"kategorie": "allg.", "text": "\"bedeutende Straße in Wien, die entlang des rechten Ufers der [[Donau]] verläuft und als wichtige Verkehrsachse im nördlichen und östlichen Teil der Stadt dient\""}, {"kategorie": "", "text": "Die Straße erstreckt sich über mehrere Bezirke, hauptsächlich über den 2. Bezirk ([[Leopoldstadt]]) und den 20. Bezirk ([[Brigittenau]]), und ist eine zentrale Verbindung zwischen verschiedenen Stadtteilen sowie ein Knotenpunkt für den Verkehr"}, {"kategorie": "", "text": "Der Handelskai wurde im 19. Jahrhundert angelegt und spielte eine zentrale Rolle in der wirtschaftlichen Entwicklung Wiens. Als direkte Uferstraße an der Donau diente er dem Handel und der Industrie, die sich entlang des Flusses ansiedelten. Die Nähe zu den Donauländen machte den Handelskai zu einem wichtigen Standort für Lagerhäuser, Fabriken und Handelsbetriebe"}, {"kategorie": "", "text": "Im Laufe der Industrialisierung wurde der Handelskai zunehmend zu einer wichtigen Verkehrsstraße für den Güterverkehr. Die Straße bot direkten Zugang zu den Frachthäfen und Lagerhäusern entlang der Donau, die für den Import und Export von Waren genutzt wurden. Mit der Zeit verlagerte sich der industrielle Schwerpunkt jedoch, und viele der ehemaligen Industrieflächen wurden umgewidmet oder neu entwickelt"}, {"kategorie": "", "text": "Durch seine Lage entlang der Donau bietet der Handelskai auch Zugang zu zahlreichen Freizeit- und Erholungsgebieten, einschließlich der Donauinsel und der Uferpromenaden. Diese Bereiche sind beliebte Ziele für Spaziergänge, Radfahren und Wassersport."}]'::jsonb, ''),
  ('noadbruckn', 'Noadbruckn', '', '', '', '', 'Nordbrücke', '[{"kategorie": "allg.", "text": "\"nördlichste Wiener Brücke über die Donau und Bestandteil der Donauufer Autobahn A 22. Sie ist vierspurig und verbindet den 20. Bezirk ([[Brigittenau]]) mit dem 21. Bezirk ([[Floridsdorf]])\""}, {"kategorie": "", "text": "Die Nordbrücke überspannt die [[Donau]] sowie die [[Donauinsel]] und den [[Donaukanal]]"}, {"kategorie": "", "text": "Sie Die wurde in den 1960er Jahren erbaut, 1964 eröffnet und im Rahmen des Ausbaus der Wiener Ringautobahn und der nördlichen Umfahrungsstraßen angelegt, um den zunehmenden Verkehrsfluss in der Stadt besser bewältigen zu können"}, {"kategorie": "", "text": "Die Nordbrücke verfügt auch über Rad- und Fußwege, die es Radfahrern und Fußgängern ermöglichen, die Donau sicher zu überqueren. Diese Wege sind Teil des [[Wiener]] Radwegenetzes und bieten eine Verbindung zwischen den nördlichen und südlichen Bezirken."}]'::jsonb, ''),
  ('suedosttangentn', 'Südosttangentn', '', '', '', '', 'Südosttangente', '[{"kategorie": "allg.", "text": "\"wichtigste und meistbefahrene Autobahn in Wien (180.000 Fahrzeuge pro Tag). Offiziell trägt sie die Bezeichnung A23 und verläuft als eine zentrale Verkehrsachse von Nordwesten nach Südosten durch die österreichische Hauptstadt\""}, {"kategorie": "", "text": "Die Wiener Südosttangente erstreckt sich über etwa 20 Kilometer durch Wien. Sie beginnt im Norden der Stadt, wo sie an die A22 [[Donauufer]] Autobahn anschließt, und verläuft in einem Bogen hauptsächlich durch die Bezirke [[Floridsdorf]], [[Donaustadt]], [[Simmering]], [[Favoriten]], und endet im Süden an der [[S]]1 Wiener Außenring Schnellstraße. Entlang ihrer Strecke überquert die A23 die Donau bei der [[Praterbrücke]] und durchquert auch dicht besiedelte Gebiete sowie Industriegebiete"}, {"kategorie": "", "text": "Der Bau der Südosttangente begann in den 1960er Jahren als Reaktion auf das wachsende Verkehrsaufkommen in Wien. Sie wurde konzipiert, um den innerstädtischen Verkehr zu entlasten und eine schnelle Verbindung zwischen den nördlichen und südlichen Bezirken sowie zwischen den verschiedenen Autobahnen zu schaffen"}, {"kategorie": "", "text": "Die ersten Abschnitte der A23 wurden in den frühen 1970er Jahren eröffnet. Seitdem wurde die Südosttangente mehrfach erweitert und modernisiert, um den steigenden Verkehrsanforderungen gerecht zu werden. Besondere Herausforderungen waren dabei die Integration neuer Verkehrswege, wie die Anbindung an die S1 Wiener Außenring Schnellstraße und die Erweiterung auf mehrere Fahrspuren in besonders stark frequentierten Bereichen."}]'::jsonb, ''),
  ('donauufaautobaun', 'Donauufaautobaun', '', '', '', '', 'Donauuferautobahn', '[{"kategorie": "allg.", "text": "\"wichtige Autobahn in Wien und Niederösterreich, die entlang des linken Ufers der [[Donau]] verläuft. Offiziell trägt sie die Bezeichnung A22, ist eine zentrale Verkehrsachse im Wiener Straßennetz und dient als Verbindung zwischen dem Stadtzentrum Wiens und den nördlichen und nordwestlichen Bezirken sowie weiter bis nach Niederösterreich\""}, {"kategorie": "", "text": "Die Donauuferautobahn wurde in den 1970er Jahren gebaut, um den Verkehr von und nach Wien effizienter zu gestalten und die Stadt an das überregionale Autobahnnetz anzubinden"}, {"kategorie": "", "text": "Die Donauuferautobahn verläuft durch landschaftlich reizvolle Gebiete entlang der Donau und bietet teilweise schöne Ausblicke auf den Fluss und die umliegenden Landschaften. Der Abschnitt durch Wien führt durch städtische Gebiete, während die weiter nördlichen Abschnitte durch ländliche Regionen und Weinbaugebiete führen."}]'::jsonb, ''),
  ('proodabruckn', 'Proodabruckn', '', '', '', '', 'Praterbrücke', '[{"kategorie": "allg.", "text": "\"bedeutende Brücke in Wien, die über die Donau führt und die Bezirke [[Leopoldstadt]] (2. Bezirk) und [[Donaustadt]] (22. Bezirk) miteinander verbindet\""}, {"kategorie": "", "text": "Sie ist Teil der [[Wiener]] Südosttangente (A23), der wichtigsten und verkehrsreichsten Autobahn in Wien, und spielt eine zentrale Rolle im städtischen und überregionalen Verkehr"}, {"kategorie": "", "text": "Die Praterbrücke überspannt die [[Donau]] sowie die [[Donauinsel]]. Sie befindet sich im südöstlichen Teil Wiens und verbindet den [[Prater]] (daher der Name) auf der westlichen Seite der Donau mit dem Gebiet rund um die [[Donaustadt]] im Osten"}, {"kategorie": "", "text": "Die Praterbrücke ist eine Stahlbrücke, die in den 1970er Jahren nach den damals modernsten technischen Standards errichtet wurde. Sie umfasst mehrere Fahrspuren in beide Richtungen und ist eine der meistbefahrenen Brücken in Wien."}]'::jsonb, ''),
  ('oaweitaschdraundbodschdrossn', 'Oaweitaschdraundbodschdrossn', '', '', '', '', 'Arbeiterstrandbadstraße', '[{"kategorie": "allg.", "text": "Straße im 21. und 22. Wiener Gemeindebezirk ([[Floridsdorf]] bzw. [[Donaustadt]])"}, {"kategorie": "", "text": "Sie verläuft von der [[Floridsdorfer]] Brücke entlang des Nordwestufers der [[Alten]] Donau, eines ehemaligen Donauarms, der heute ein stehendes Gewässer ist und als Freizeit- und Erholungsgebiet genutzt wird, bis zur [[Wagramer]] Straße"}, {"kategorie": "", "text": "Die Arbeiterstrandbadstraße hat ihren Namen von dem gleichnamigen Strandbad, das in den 1920er Jahren eröffnet wurde"}, {"kategorie": "", "text": "Das [[Arbeiterstrandbad]] wurde in der Zwischenkriegszeit als eine der ersten großen Erholungsanlagen für die Arbeiterbewegung errichtet. Es sollte den Arbeitern und ihren Familien einen günstigen Zugang zu Freizeitaktivitäten und Erholung im Freien bieten"}, {"kategorie": "", "text": "Die Arbeiterstrandbadstraße führt durch eine attraktive Wohngegend, die von ihrer Nähe zur Alten Donau profitiert. Entlang der Straße befinden sich vor allem Wohnhäuser, Gärten, und einige öffentliche Einrichtungen. Die Nähe zur Alten Donau macht die Straße besonders beliebt bei Menschen, die einen Zugang zu Freizeitaktivitäten im Grünen schätzen."}]'::jsonb, ''),
  ('oaweitaschdraundbood', 'Oaweitaschdraundbood', '', '', '', '', 'Arbeiterstrandbad', '[{"kategorie": "allg.", "text": "historische und beliebte Badeanstalt an der [[Alten]] Donau im 21. Wiener Gemeindebezirk ([[Floridsdorf]])"}, {"kategorie": "", "text": "Es wurde ursprünglich in den 1920er Jahren errichtet und war eines der ersten Strandbäder Wiens, das speziell für die Arbeiterklasse geschaffen wurde. Das Bad liegt direkt am Nordwestufer der Alten Donau und bietet seinen Besuchern zahlreiche Freizeit- und Erholungsmöglichkeiten in naturnaher Umgebung"}, {"kategorie": "", "text": "Das Arbeiterstrandbad wurde 1918 im Rahmen der Wiener Arbeiterbewegung gegründet, um der Arbeiterklasse einen erschwinglichen und leicht zugänglichen Ort für Erholung und Freizeitgestaltung zu bieten. In den Jahren nach seiner Eröffnung entwickelte sich das Bad zu einem wichtigen sozialen Treffpunkt für Arbeiterfamilien"}, {"kategorie": "", "text": "Die Umgebung des Bades ist geprägt von der naturnahen Landschaft der Alten Donau. Die Uferbereiche sind mit Bäumen und Sträuchern bepflanzt, die Schatten spenden und zur entspannten Atmosphäre beitragen. Der Zugang zum Wasser erfolgt über sanfte Uferbereiche, die das Baden besonders angenehm machen."}]'::jsonb, ''),
  ('angelibood', 'Angelibood', '', '', '', '', 'Angelibad', '[{"kategorie": "allg.", "text": "beliebtes öffentliches Freibad an der Alten Donau im 21. Wiener Gemeindebezirk ([[Floridsdorf]])"}, {"kategorie": "", "text": "Es liegt am Nordwestufer der [[Alten]] Donau und bietet den Besuchern eine idyllische Umgebung zum Schwimmen, Sonnenbaden und Entspannen"}, {"kategorie": "", "text": "Mit seiner entspannten Atmosphäre und der Nähe zur Natur ist das Angelibad ein fester Bestandteil der Wiener Badekultur und bietet insbesondere Familien und Ruhesuchenden eine tolle Möglichkeit, dem Trubel der Stadt zu entfliehen."}]'::jsonb, ''),
  ('schuettauschdrossn', 'Schüttauschdrossn', '', '', '', '', 'Schüttaustraße', '[{"kategorie": "allg.", "text": "\"Straße im 22. Wiener Gemeindebezirk ([[Donaustadt]]), die parallel zur [[Alten]] Donau durch [[Kaisermühlen]] verläuft und in einem Bereich liegt, der für seine ruhige, grüne Umgebung und den direkten Zugang zur [[Alten]] Donau bekannt ist\""}, {"kategorie": "", "text": "Entlang der Schüttaustraße finden sich hauptsächlich Wohnhäuser, viele davon mit Blick auf die Alte Donau. Die Straße ist von Bäumen gesäumt, was zur angenehmen Atmosphäre beiträgt. Es gibt sowohl moderne Wohnanlagen als auch ältere, historische Gebäude, die der Straße ihren besonderen Charakter verleihen"}, {"kategorie": "hist.", "text": "Die Schüttaustraße wurde am 27. Mai 1873 nach der \"Schüttau\" benannt. Hierunter versteht man eine Insel (\"Schütt\" oder \"Anschütt\") im unregulierten Donaustrom mit Auwaldbeständen. Der Begriff wurde für neu auftauchende Inseln nach Hochwässern verwendet. Schüttauen können über die Jahrhunderte an vielen Stellen der Wiener Donau verortet werden. Eine länger bestehende Anschütt mit der Bezeichnung \"Schüttau\" befand sich östlich des Stadtguts. Sie wurde im Zuge der [[Donauregulierung]] (1870-1875) planiert und verschwand."}]'::jsonb, ''),
  ('gemeindebau', 'Gemeindebau', '', '', '', '', 'Gemeindebau', '[{"kategorie": "allg.", "text": "\"volkstümliche Bezeichnung für eine Wohnanlage, die im Auftrag der Gemeinde Wien bzw. der Wiener Stadtverwaltung errichtet und verwaltet wird\""}, {"kategorie": "", "text": "In Wien bezieht sich der Begriff speziell auf die von der Stadt Wien gebauten und betriebenen sozialen Wohnbauten, die ursprünglich dazu gedacht waren, einkommensschwächeren Bevölkerungsschichten qualitativ hochwertigen und erschwinglichen Wohnraum zu bieten"}, {"kategorie": "", "text": "Gemeindebauten in Wien sind ein zentrales Element des sozialen Wohnungsbaus, der es Menschen mit geringem bis mittlerem Einkommen ermöglicht, Zugang zu leistbarem Wohnraum zu erhalten. Die Mieten in diesen Wohnungen sind in der Regel unter dem Marktniveau, um die soziale Durchmischung und die Chancengleichheit zu fördern"}, {"kategorie": "", "text": "Viele Wiener Gemeindebauten zeichnen sich durch eine eigene, oft monumentale Architektur aus, die insbesondere in den 1920er und 1930er Jahren im Rahmen des sogenannten „Roten Wien“ entstand. Diese Gebäude sind häufig mit großzügigen Innenhöfen, Gemeinschaftseinrichtungen und Grünflächen ausgestattet, um den Bewohnern eine hohe Lebensqualität zu bieten"}, {"kategorie": "", "text": "Bekannt als die größten Wiener Wohnbaukomplexe und als Symbol für das \"Rote Wien\" sind insbesondere der [[Karl-Marx-Hof]], der [[Sandleitenhof]], der [[George-Washington-Hof]], der [[Rabenhof]] und der [[Goethe-Hof]]"}]'::jsonb, ''),
  ('goethehof', 'Goethehof', '', '', '', '', 'Goethehof', '[{"kategorie": "allg.", "text": "\"eine der markantesten und historisch bedeutendsten Wohnanlagen in Wien, gelegen in [[Kaisermühlen]] im 22. Wiener Gemeindebezirk ([[Donaustadt]])\""}, {"kategorie": "", "text": "Er wurde zwischen 1928 und 1930 im Rahmen des umfangreichen Wohnbauprogramms der sozialdemokratisch geführten Stadtverwaltung errichtet, die als [[Rotes Wien]] in die Geschichte einging. Diese Periode war geprägt von einer ambitionierten Sozialpolitik, die darauf abzielte, erschwinglichen Wohnraum für die Arbeiterklasse zu schaffen, und der Goethehof ist ein herausragendes Beispiel für diese Bestrebungen"}, {"kategorie": "", "text": "Der Goethehof ist nach dem deutschen Dichter Johann Wolfgang von Goethe benannt und gehört zu den sogenannten [[Gemeindebauten]] in Wien"}, {"kategorie": "", "text": "Die Anlage umfasst etwa 750 Wohnungen und besteht aus mehreren miteinander verbundenen Gebäuden, die sich um großzügige, begrünte Innenhöfe gruppieren"}, {"kategorie": "hist.", "text": "Historisch erlangte der Goethehof traurige Berühmtheit durch seine Rolle während der [[Februarkämpfe]] von 1934. Diese bewaffneten Auseinandersetzungen zwischen sozialdemokratischen Schutzbündlern und der Regierungstruppe ([[Heimwehr]] und Polizei) waren Teil des österreichischen Bürgerkriegs, der letztlich zur Errichtung des austrofaschistischen Ständestaates führte. Der Goethehof, wie viele andere Gemeindebauten, wurde zu einem symbolischen Verteidigungspunkt der sozialistischen Arbeiterbewegung. Die Kämpfe dort endeten mit einer Niederlage der Schutzbündler, und der Goethehof blieb eine Mahnung an die politischen Spannungen der Zwischenkriegszeit"}, {"kategorie": "", "text": "Nach dem Zweiten Weltkrieg wurde der Goethehof, wie viele andere Gemeindebauten, renoviert und modernisiert. Er steht heute unter Denkmalschutz und ist weiterhin ein lebendiges Wohnviertel, das den sozialen Wohnbaugedanken des Roten Wien weiterträgt. Seine Geschichte und Architektur machen ihn zu einem wichtigen Zeugnis der Wiener Stadtgeschichte und zu einem Symbol für die sozialen und politischen Kämpfe des 20. Jahrhunderts in Österreich"}]'::jsonb, ''),
  ('roobnhof', 'Roobnhof', '', '', '', '', 'Rabenhof', '[{"kategorie": "allg.", "text": "\"bedeutende Wohnanlage in Wien, die sich im 3. Wiener Gemeindebezirk ([[Landstraße]]) befindet\""}, {"kategorie": "", "text": "Wie viele andere Wiener Gemeindebauten wurde der Rabenhof in der Zeit des à„Roten Wien“ in den 1920er Jahren errichtet, einer Periode, in der die sozialdemokratische Stadtregierung ein umfangreiches Programm zum Bau von erschwinglichem Wohnraum für die Arbeiterklasse initiierte"}, {"kategorie": "", "text": "Der Rabenhof wurde zwischen 1925 und 1928 nach den Plänen der Architekten Heinrich Schmid und Hermann Aichinger gebaut. Die Anlage umfasst mehrere miteinander verbundene Gebäudekomplexe, die sich um Innenhöfe gruppieren, ein typisches Merkmal der Gemeindebauten dieser Zeit. Insgesamt umfasst der Rabenhof etwa 1100 Wohnungen und war bei seiner Fertigstellung eine der größten Wohnanlagen Wiens"}, {"kategorie": "", "text": "Der Rabenhof ist nicht nur ein Ort zum Wohnen, sondern auch ein sozialer und kultureller Treffpunkt. Besonders hervorzuheben ist das Rabenhof-Theater, das sich im Zentrum der Anlage befindet. Ursprünglich als Kino und Veranstaltungsraum konzipiert, hat sich das Theater bis heute als bedeutende Wiener Kleinkunstbühne etabliert, auf der Kabarett, Theaterstücke und andere kulturelle Veranstaltungen stattfinden."}]'::jsonb, ''),
  ('roobngossn', 'Roobngossn', '', '', '', '', 'Rabengasse', '[{"kategorie": "allg.", "text": "\"ruhigere Straße im 3. Wiener Gemeindebezirk ([[Landstraße]]) mit einer interessanten, historischen Legende\""}, {"kategorie": "", "text": "Der Name der Gasse leitet sich vermutlich von den Raben ab, die sich in großer Zahl bei den Wohnungen des hier angesiedelten Freimanngesindels niederließen. Das Freimanngesindel bestand aus dem Freimann, einem städtischen Abdecker (Schinder), und seinen Abdeckerknechten, die für die Beseitigung von Tierkadavern verantwortlich waren. Da bei ihren Unterkünften oft abgehäutetes Vieh herumlag, zog dies die Raben an"}, {"kategorie": "", "text": "Diese Siedlung, die als \"Freimannsgschmölz in der Rabengstätten\" bekannt war, wurde nach der [[Zweiten]] Türkenbelagerung von 1683 in Richtung St. Marxer Linie verlegt"}, {"kategorie": "", "text": "Die Straße wurde 1929 um den Abschnitt der [[Rüdengasse]] verlängert und liegt heute in einem ruhigen, wohnlichen Viertel. Inmitten dieser Wohnstraße befindet sich der [[Rabenhof]], ein bedeutender [[Gemeindebau]], der zwischen 1925 und 1928 errichtet wurde"}, {"kategorie": "", "text": "In diesem historischen Gemeindebau ist auch das [[Rabenhof]] Theater untergebracht, das sich als eigenständige Bühne mit einem breiten Programm von Literatur bis Politsatire einen Namen gemacht hat."}]'::jsonb, ''),
  ('ruedngossn', 'Rüdngossn', '', '', '', '', 'Rüdengasse', '[{"kategorie": "allg.", "text": "\"historische Gasse im 3. Wiener Gemeindebezirk ([[Landstraße]]) im Stadtteil [[Erdberg]]\", die nach dem historischen Rüdenhof benannt, der eine zentrale Rolle in der kaiserlichen Jagdkultur spielte\""}, {"kategorie": "", "text": "Der Rüdenhof, der sich zwischen der heutigen [[Dietrichgasse]] und der [[Erdbergstraße]] befand, war ursprünglich ein Jagdhaus, das möglicherweise schon in der Babenbergerzeit als solches genutzt wurde. Es wird vermutet, dass es mit dem Erdberger Meierhof in Verbindung stand. Eine bekannte Überlieferung besagt, dass in der Nähe dieses Meierhofs der englische König Richard Löwenherz am 23. Dezember 1192 gefangen genommen wurde"}, {"kategorie": "", "text": "Im 16. Jahrhundert ließ Kaiser [[Maximilian]] I. das \"Große Rüdenhaus\" als offizielles Gebäude der kaiserlichen Jagd in [[Erdberg]] errichten, das unter der Leitung eines Rüdenmeisters und später zweier (Ober- und Unterrüdenmeister) stand"}, {"kategorie": "", "text": "Das Rüdenhaus diente zur Zucht und Pflege der kaiserlichen Jagdhunde, die in der Blütezeit über hundert Tiere zählte. Die Hunde wurden vor allem mit Brot und Getreidebrei gefüttert"}, {"kategorie": "", "text": "Das Rüdenhaus wurde 1772 nach einer Umstrukturierung der kaiserlichen Jagd aufgelassen und das Gebäude an die Gemeinde Erdberg verkauft. Eine Gedenktafel in der [[Erdbergstraße]] 41 erinnert heute an den historischen Rüdenhof"}, {"kategorie": "", "text": "Die Rüdengasse ist heute eine ruhige Wohnstraße, die in ihrem Namen auf die reiche Geschichte der Jagd und Tierpflege des kaiserlichen Hofes verweist und einen wichtigen Teil der Erdberger Geschichte darstellt."}]'::jsonb, ''),
  ('diitrichgossn', 'Diitrichgossn', '', '', '', '', 'Dietrichgasse', '[{"kategorie": "allg.", "text": "\"ruhigere Wohnstraße im 3. Wiener Gemeindebezirk ([[Landstraße]]) im Stadtteil [[Erdberg]]\""}, {"kategorie": "", "text": "Sie wurde 1830 nach dem Küchengärtner Georg Dietrich benannt. Dieser stammte aus Oberlaa (*3. Oktober 1750) und ließ sich in Erdberg nieder, wo er um das Jahr 1800 das erste Haus in der nach ihm benannten Gasse erbaute. Er stellte sein Grundstück für die Anlage der Straße zur Verfügung, weshalb die Dietrichgasse dann auch seinen Namen erhielt"}, {"kategorie": "", "text": "Ein historisch bedeutendes Gebäude, der [[Rüdenhof]], lag einst zwischen der Dietrichgasse und der [[Rüdengasse]] und war ein Zentrum der kaiserlichen Jagdhundezucht"}, {"kategorie": "", "text": "An der Dietrichgasse 35-37 befindet sich heute ein [[Gemeindebau]], der auf dem Gelände der ehemaligen \"Wällischen Gärten\" errichtet wurde. Diese Gärten waren bis ins 19. Jahrhundert ein wichtiger Versorgungsfaktor für die Wiener Bevölkerung"}, {"kategorie": "", "text": "Die Grundstücke gehörten einst der aus Verona stammenden Oria della Scala, die sie 1445 dem Augustinerorden schenkte. Die Gärten wurden aufgrund der Herkunft der Stifterin aus dem \"Welschland\" (Norditalien) bis zur Bebauung im 19. Jahrhundert als \"Wällische Gärten\" bezeichnet"}, {"kategorie": "", "text": "Heute verbindet die Dietrichgasse historische Aspekte der Wiener Stadtentwicklung mit dem modernen Wohnen in Gemeindebauten."}]'::jsonb, ''),
  ('baumgossn', 'Baumgossn', '', '', '', '', 'Baumgasse', '[{"kategorie": "allg.", "text": "\"eine der ältesten Straßenzüge des dritten Bezirks ([[Landstraße]]), deren Existenz bis ins 17. Jahrhundert nachgewiesen werden kann\""}, {"kategorie": "", "text": "Die Gasse wurde nach den Obstgärten und Baumschulen benannt, die einst in dieser Gegend angelegt waren. Sie war bis ins 19. Jahrhundert nur dünn besiedelt, mit überwiegend ebenerdigen Höfen und dörflichen [[Biedermeierbauten]], die jedoch im 20. Jahrhundert im Zuge von städtebaulichen Maßnahmen weitgehend abgerissen wurden"}, {"kategorie": "", "text": "Ein bedeutender Wandel in der Baumgasse erfolgte in den Jahren 1925 bis 1929 mit der Errichtung des [[Rabenhofs]], einer großangelegten Gemeindebauanlage auf dem Gelände der ehemaligen Krimsky-Kaserne. Der Rabenhof, der den Charakter der Gasse prägt, wurde in den 1950er-Jahren modernisiert und erweitert, wodurch viele der älteren Bauten durch mehrgeschossige Wohnanlagen ersetzt wurden"}, {"kategorie": "", "text": "Eines dieser Gebäude ist das Wohnhaus Baumgasse 43, das als Teil des Rabenhof-Komplexes errichtet wurde. Die Architektur des Gebäudes knüpft an den Stil des Rabenhofes an, insbesondere durch die Klinkerverkleidung des Erdgeschosses, jedoch mit einer schlichteren Gestaltung der Wohngeschosse und Balkone"}, {"kategorie": "", "text": "Heute dominiert die Baumgasse durch ihre moderne Wohnbebauung und ist ein lebendiges Wohngebiet mit einer Mischung aus neuen und historischen Elementen."}]'::jsonb, ''),
  ('biidameiabautn', 'Biidameiabautn', '', '', '', '', 'Biedermeierbauten', '[{"kategorie": "allg.", "text": "\"Wohn- und Gebäudearchitektur, die während der [[Biedermeierzeit]] zwischen dem [[Wiener]] Kongress (1814/1815) und der Revolution von 1848 in Wien entstand\""}, {"kategorie": "", "text": "Diese Epoche ist geprägt von einer Rückbesinnung auf das Private und einer gezielten Abkehr vom politischen und öffentlichen Leben, als Reaktion auf den repressiven [[Metternichschen]] Polizeistaat mit seiner Zensur und dem Ausschluss des Bürgertums aus politischen Entscheidungen. Der Begriff „Biedermeier“ wurde zunächst für den Möbelstil verwendet, der durch schlichte, funktionale und elegante Formen gekennzeichnet war, später aber auch auf die bürgerliche Kultur und Architektur der Zeit übertragen"}, {"kategorie": "", "text": "Die Biedermeierarchitektur in Wien zeichnet sich durch ihre klare und unaufgeregte Gestaltung aus. Die Gebäude waren oft von schlichter Eleganz, mit einem Schwerpunkt auf Wohnkomfort und der Schaffung eines behaglichen, ästhetischen Lebensraums für das aufstrebende Bürgertum"}, {"kategorie": "", "text": "Bauten dieser Zeit neigen dazu, weniger monumental zu wirken als die Prachtbauten des [[Klassizismus]], sondern waren funktional und für die Bedürfnisse von Familien und Privatpersonen ausgelegt"}, {"kategorie": "", "text": "Typische Merkmale Wiener Biedermeierbauten: (i) schlichte, elegante Fassaden ohne übermäßige Verzierungen;  (ii) Verwendung von Naturmaterialien wie Holz und Stein, die zu einer harmonischen Wohnatmosphäre beitragen, (iii) einfache, aber funktionale Gestaltung der Innenräume, oft mit Möbeln im Biedermeierstil ausgestattet, (iv) Fokus auf helle, lichtdurchflutete Räume mit großen Fenstern, (v) Liebe zum Detail bei Fenstern, Türen und Verzierungen, die meist auf bürgerlichen Geschmack und Wohlstand hinwiesen, (vi) Integration von begrünten Innenhöfen und kleinen Gärten, die Rückzugsorte für das private Leben boten"}, {"kategorie": "", "text": "Biedermeierbauten spiegeln die Sehnsucht des Bürgertums nach einer Rückzugswelt wider, in der Kunst, Kultur und gesellschaftliches Leben in einem kleineren, intimen Rahmen stattfanden. In der Wohnarchitektur der Biedermeierzeit wird der Wohnraum zur „heilen Welt“ und zum Mittelpunkt des Lebens, weit entfernt von den politischen Wirren und der öffentlichen Sphäre"}, {"kategorie": "", "text": "Wien war während der [[Biedermeierzeit]] ein zentraler Ort dieser kulturellen Strömungen, und viele der Bauwerke, die aus dieser Zeit stammen, prägen noch heute das Stadtbild. Insbesondere in den damaligen Vororten Wiens, wie der [[Landstraße]] (3. Bezirk) oder [[Wieden]] (4. Bezirk), entstanden zahlreiche dieser charakteristischen Bauten, die sich durch ihre schlichte Schönheit und Funktionalität auszeichnen."}]'::jsonb, ''),
  ('biidameiazeit', 'Biidameiazeit', '', '', '', '', 'Biedermeierzeit', '[{"kategorie": "allg.", "text": "\"historische Epoche, die sich in den Ländern des [[Deutschen]] Bundes von etwa 1815 bis 1848 erstreckte\""}, {"kategorie": "", "text": "Die Epoche begann mit dem Ende des [[Wiener]] Kongresses, der Europa nach den [[Napoleonischen]] Kriegen neu ordnete, und endete mit den bürgerlichen [[Revolutionen]] von 1848"}, {"kategorie": "", "text": "Die Biedermeierzeit war geprägt von  von einer Rückbesinnung auf das Private und einer gezielten Abkehr vom politischen und öffentlichen Leben, als Reaktion auf den repressiven [[Metternichschen]] Polizeistaat mit seiner Zensur und dem Ausschluss des Bürgertums aus politischen Entscheidungen"}, {"kategorie": "", "text": "Im kulturellen Bereich steht der Begriff Biedermeier für eine Zeit, in der sich das Bürgertum zunehmend auf das private und häusliche Leben konzentrierte. Typisch für diese Epoche ist die Flucht ins Idyll und die Betonung auf häusliche Gemütlichkeit. Das Bürgertum entwickelte eine Vorliebe für behagliche Wohnkultur, die sich etwa in der Architektur und Innenraumgestaltung niederschlug"}, {"kategorie": "", "text": "Der Begriff „Biedermeier“ selbst geht auf die fiktive Figur Gottlieb Biedermaier zurück, die von den Schriftstellern Ludwig Eichrodt und Adolf Kußmaul erfunden wurde. Sie karikierten den spießbürgerlichen und unpolitischen Charakter des damaligen Bürgertums. Ursprünglich negativ konnotiert, steht der Begriff heute jedoch eher wertneutral für die bürgerliche Kultur dieser Zeit"}, {"kategorie": "", "text": "Dem Biedermeier als Epoche der Anpassung und des Rückzugs stand die politisch revolutionäre Bewegung des [[Vormärz]] gegenüber. Literaten wie Georg Büchner und Heinrich Heine prangerten die politischen Missstände ihrer Zeit an und setzten sich für Freiheit und Revolution ein"}, {"kategorie": "", "text": "Zusammenfassend kann das Biedermeier als Zeit der häuslichen Kultur, der bürgerlichen Gemütlichkeit und des Rückzugs ins Private verstanden werden, die im Gegensatz zu den politischen Umbrüchen der [[Vormärz-Bewegung]] stand."}]'::jsonb, ''),
  ('vuamaeaz', 'Vuamäaz', '', '', '', '', 'Vormärz', '[{"kategorie": "allg.", "text": "\"politische Periode in den deutschen Staaten zwischen dem [[Wiener]] Kongress (1814/1815) und der [[Revolution]] von 1848\""}, {"kategorie": "", "text": "Die Epoche war geprägt durch das Aufkommen von Nationalismus, Liberalismus und Sozialismus sowie durch die dagegen gerichtete restaurative Politik der repressiven Monarchien, insbesondere unter dem Einfluss des [[Metternichschen]] Polizeistaates"}, {"kategorie": "", "text": "Nach den [[Napoleonischen]] Kriegen und dem [[Wiener]] Kongress strebten die konservativen Mächte, vor allem Österreich, Preußen und Russland, eine Restauration der alten monarchischen Ordnung an. Der [[Deutsche]] Bund wurde als loser Staatenbund gegründet, um den Status quo zu sichern"}, {"kategorie": "", "text": "Klemens Wenzel Lothar von Metternich, der österreichische Staatsmann, dominierte die Politik dieser Zeit und setzte durch die [[Karlsbader]] Beschlüsse von 1819 eine strikte Zensur sowie das Verbot politischer Vereinigungen durch, um jegliche revolutionäre Bewegungen zu unterdrücken. Besonders betroffen von dieser Repression waren Schriftsteller, Zeitungen und politische Organisationen"}, {"kategorie": "", "text": "Während der Vormärz ein Zeitalter der politischen Unterdrückung war, brachte er zugleich tiefgreifende wirtschaftliche Veränderungen mit sich. Industrialisierung, die Entwicklung des Frühkapitalismus und der Ausbau der Eisenbahnen veränderten die Gesellschaft nachhaltig. Gleichzeitig entstand großer sozialer Unmut, insbesondere durch die Verarmung breiter Bevölkerungsschichten, was als [[Pauperismus]] bekannt wurde"}, {"kategorie": "", "text": "Der wirtschaftliche Wandel führte zu einem wachsenden Bürgertum, das jedoch politisch weitgehend entrechtet war. Diese politische Ohnmacht des Bürgertums führte zu einer zunehmenden Rückkehr ins Private, die mit dem [[Biedermeier]] verbunden ist, einer kulturellen Strömung, die häusliche Gemütlichkeit und Rückzug in das Familienleben betonte"}, {"kategorie": "", "text": "Trotz massiver staatlicher Repression wuchs die Opposition, besonders in den 1840er Jahren, und erreichte schließlich mit der [[Märzrevolution]] von 1848 ihren Höhepunkt, als Bürger in vielen deutschen Staaten eine [[konstitutionelle]] Monarchie und nationale Einheit forderten."}]'::jsonb, ''),
  ('pauparismus', 'Pauparismus', '', '', '', '', 'Pauperismus', '[{"kategorie": "allg.", "text": "\"extreme Verarmung und Verelendung großer Teile der Bevölkerung, insbesondere der Arbeiterschicht, die sich im Zeitraum vor und während der frühen Industrialisierung entwickelte\""}, {"kategorie": "", "text": "Der Begriff leitet sich vom lateinischen Wort pauper (arm) ab und beschreibt ein Phänomen, das ab Ende des 18. Jahrhunderts in England sichtbar wurde und sich auch in anderen europäischen Ländern, wie im [[Kaisertum]] Österreich während des [[Vormärz]] zeigte"}, {"kategorie": "", "text": "Der Pauperismus hatte auch auf Wien im 19. Jahrhundert gravierende Auswirkungen. Wie in anderen europäischen Städten, führte die wachsende Verarmung der Bevölkerung zu sozialen, wirtschaftlichen und politischen Spannungen"}, {"kategorie": "", "text": "Der Pauperismus führte zu steigender Unzufriedenheit in der Bevölkerung, was zu sozialen Unruhen und Protesten führte. Die Verelendung, Arbeitslosigkeit und die steigenden Lebenshaltungskosten brachten viele Wiener an den Rand des Existenzminimums. Diese Zustände mündeten schließlich in die politische Unruhe des [[Vormärz]] und trugen maßgeblich zur [[Revolution]] von 1848 bei, in der die Forderungen nach sozialen Reformen, politischen Rechten und besseren Lebensbedingungen laut wurden."}]'::jsonb, ''),
  ('ruednhof', 'Rüdnhof', '', '', '', '', 'Rüdenhof', '[{"kategorie": "allg.", "text": "\"historisch bedeutendes Zentrum der kaiserlichen Jagdhundezucht und offizielles Gebäude der kaiserlichen Jägerei im 3. Wiener Gemeindebezirk ([[Landstraße]]) im Stadtteil [[Erdberg]]\""}, {"kategorie": "", "text": "Die Geschichte des Rüdenhofs reicht bis in die Babenbergerzeit zurück, als das Gelände vermutlich als Jagdhaus in der Vorstadt von Wien genutzt wurde. Es befand sich in der Gegend von [[Erdberg]], möglicherweise in der Nähe des damaligen Erdberger Meierhofs"}, {"kategorie": "", "text": "Der Rüdenhof, auch bekannt als \"Großes Rüdenhaus\", wurde im 16. Jahrhundert unter Kaiser [[Maximilian]] I. offiziell eingerichtet. Das Gebäude diente der Pflege und Zucht der kaiserlichen Jagdhunde und wurde von einem Rüdenmeister verwaltet. Es beherbergte während seiner Blütezeit über hundert Jagdhunde, die vorwiegend mit Brot und Getreidebrei gefüttert wurden. Weitere Bedienstete wie Rüdenknechte, ein Torwächter und ein Bäcker kümmerten sich um die Bedürfnisse der Tiere"}, {"kategorie": "", "text": "Nach einer Umstrukturierung der kaiserlichen Jägerei wurde der Rüdenhof 1772 aufgelassen und an die Gemeinde [[Erdberg]] verkauft. Später wurde das Gebäude auch als \"Wäscherburg\" bekannt, da es zahlreiche Wäscherfamilien beherbergte. Diese Gebäude wurde jedoch 1872 abgerissen"}, {"kategorie": "", "text": "Der Rüdenhof war somit ein zentrales Element der k.u.k. Jagdkultur und spielte eine bedeutende Rolle in der Pflege und Haltung der kaiserlichen Jagdhunde"}]'::jsonb, ''),
  ('saundleitnhof', 'Saundleitnhof', '', '', '', '', 'Sandleitenhof', '[{"kategorie": "allg.", "text": "\"eine der größten und bedeutendsten kommunalen Wohnanlagen in Wien, gelegen im 16. Wiener Gemeindebezirk ([[Ottakring]])\""}, {"kategorie": "", "text": "Er wurde zwischen 1924 und 1928 als Teil des umfassenden Wohnbauprogramms des à„Roten Wien“ errichtet, das von der sozialdemokratischen Stadtregierung initiiert wurde, um die Wohnverhältnisse der Arbeiterklasse nachhaltig zu verbessern. Der Sandleitenhof ist nicht nur ein herausragendes Beispiel für die Architektur und Stadtplanung dieser Epoche, sondern auch ein Symbol für die sozialen und politischen Ideale, die das à„Rote Wien“ verkörperte"}, {"kategorie": "", "text": "Der Bau des Sandleitenhofs begann im Jahr 1924 und wurde 1928 abgeschlossen. Die Architekten des Projekts, darunter Karl Ehn, Robert Oerley, und andere, entwarfen eine weitläufige Wohnanlage, die sich über eine Fläche von etwa 42.000 Quadratmetern erstreckt und ursprünglich 1.587 Wohnungen umfasste. Die Anlage besteht aus mehreren miteinander verbundenen Wohnblöcken, die um großzügige Innenhöfe angeordnet sind, ein typisches Merkmal der Wiener Gemeindebauten aus dieser Zeit"}, {"kategorie": "", "text": "Der Sandleitenhof spielte eine wichtige Rolle in den politischen Auseinandersetzungen der Zwischenkriegszeit. Während der [[Februarkämpfe]] von 1934, einem bewaffneten Konflikt zwischen der sozialistischen Arbeiterbewegung und der austrofaschistischen Regierung, wurde der Sandleitenhof zu einem der zentralen Orte des Widerstands. Die Anlage wurde zu einem Symbol des Kampfes der Arbeiterbewegung gegen den aufkommenden Faschismus in Österreich"}, {"kategorie": "", "text": "Heute ist der Sandleitenhof weiterhin ein lebendiges Wohnviertel und ein bedeutendes Denkmal des sozialen Wohnbaus in Wien. Die Anlage steht unter Denkmalschutz und ist ein beliebter Wohnort, der seinen historischen Charakter bewahrt hat."}]'::jsonb, ''),
  ('saundleitngossn', 'Saundleitngossn', '', '', '', '', 'Sandleitengasse', '[{"kategorie": "allg.", "text": "\"Straße im 16. Wiener Gemeindebezirk ([[Ottakring]]), die eng mit der Geschichte des sozialen Wohnbaus in Wien verbunden ist\""}, {"kategorie": "", "text": "Die Gasse verläuft in einem Viertel, das stark von den [[Gemeindebauten]] des à„Roten Wien“ geprägt ist, insbesondere durch den [[Sandleitenhof]], eine der größten und bekanntesten Wohnanlagen dieser Ära"}, {"kategorie": "", "text": "Die Gasse liegt in einem Viertel, das während der Zwischenkriegszeit stark von der sozialdemokratischen Stadtregierung Wiens gestaltet wurde. Ottakring war damals ein Arbeiterbezirk, der von sozialen Problemen wie Überbevölkerung, schlechten Wohnverhältnissen und Armut betroffen war. Die Errichtung von [[Gemeindebauten]] wie dem [[Sandleitenhof]] und die Entwicklung von Straßen wie der Sandleitengasse waren Teil der Bemühungen der Stadtverwaltung, die Lebensbedingungen der Menschen in diesen Gebieten zu verbessern"}, {"kategorie": "", "text": "Heute ist die Sandleitengasse eine typische Wohnstraße in Wien, die von mehrstöckigen Wohnhäusern und [[Gemeindebauten]] gesäumt wird. Sie bietet Zugang zu wichtigen sozialen Einrichtungen und öffentlichen Verkehrsmitteln und ist Teil eines lebendigen Wohnviertels. Die Gasse hat sich ihren historischen Charakter bewahrt und steht symbolisch für die sozialen Errungenschaften des à„Roten Wien“."}]'::jsonb, ''),
  ('schuettlschdrossn', 'Schüttlschdrossn', '', '', '', '', 'Schüttelstraße', '[{"kategorie": "allg.", "text": "\"bedeutende Verkehrsstraße im 2. Wiener Gemeindebezirk ([[Leopoldstadt]])\""}, {"kategorie": "", "text": "Sie erstreckt sich entlang des rechten Ufers des [[Donaukanals]], einer künstlich angelegten Wasserstraße, die die Wiener Innenstadt durchquert. Die Straße verläuft vom [[Praterstern]] im Nordwesten bis zur [[Erdberger]] Lände im Südosten, wobei sie in westlicher Richtung parallel zum Donaukanal verläuft"}, {"kategorie": "", "text": "Der Name \"Schüttelstraße\" leitet sich vom Begriff \"Schütten\" ab, was auf die Praxis hinweist, Erdmassen aufzuschütten. Diese Maßnahme diente insbesondere dem Hochwasserschutz. In der Vergangenheit wurden entlang des Donaukanals Dämme und Aufschüttungen errichtet, um die angrenzenden Gebiete vor Überflutungen zu schützen. Die Straße entstand somit auf diesen aufgeschütteten Flächen und erhielt ihren Namen entsprechend dieser historischen Bauweise"}, {"kategorie": "", "text": "Entlang der Schüttelstraße befinden sich zahlreiche Wohnhäuser, die teils noch aus dem späten 19. und frühen 20. Jahrhundert stammen und damit den architektonischen Charakter der Straße prägen. Daneben gibt es auch moderne Gebäude, Bürokomplexe und Gewerbeimmobilien, die die Funktion der Straße als urbanes Lebens- und Arbeitsumfeld unterstreichen"}, {"kategorie": "", "text": "Durch ihre Lage am Donaukanal bietet die Schüttelstraße auch einen hohen Freizeitwert. Der Donaukanal ist ein beliebtes Naherholungsgebiet für Wiener und Touristen. Entlang des Kanals gibt es zahlreiche Cafés, Bars und Restaurants, die zum Verweilen einladen."}]'::jsonb, ''),
  ('radetkyplotz', 'Radetkyplotz', '', '', '', '', 'Radetzkyplatz', '[{"kategorie": "allg.", "text": "\"markanter Platz im 3. Wiener Gemeindebezirk ([[Landstraße]])\""}, {"kategorie": "", "text": "Benannt ist er nach dem berühmten österreichischen Feldmarschall Josef Wenzel Graf Radetzky von Radetz, einer der bedeutendsten militärischen Persönlichkeiten Österreichs im 19. Jahrhundert"}, {"kategorie": "", "text": "Der Radetzkyplatz liegt in der Nähe des [[Donaukanals]] und ist von mehreren wichtigen Straßen umgeben, darunter die [[Radetzkystraße]], die [[Weißgerberlände]] und die [[Löwengasse]]. Diese zentrale Lage macht den Platz zu einem wichtigen Knotenpunkt für den Verkehr und gleichzeitig zu einem beliebten Aufenthaltsort für die Anwohner"}, {"kategorie": "", "text": "Der Radetzkyplatz ist von einer Reihe von historischen Gebäuden umgeben, die überwiegend aus der [[Gründerzeit]] stammen. Diese Gebäude verleihen dem Platz eine klassische Wiener Atmosphäre und prägen das Erscheinungsbild des Viertels"}, {"kategorie": "", "text": "Darüber hinaus befindet sich am Radetzkyplatz auch die Radetzkykirche, eine katholische Pfarrkirche, die ebenfalls nach Feldmarschall Radetzky benannt ist."}]'::jsonb, ''),
  ('gruendazeit', 'Gründazeit', '', '', '', '', 'Gründerzeit', '[{"kategorie": "allg.", "text": "\"Epoche in der mitteleuropäischen Geschichte, die etwa von den 1840er Jahren bis zum Ausbruch des Ersten Weltkriegs 1914 andauerte. Der Begriff „Gründerzeit“ bezieht sich insbesondere auf die Phase des wirtschaftlichen Aufschwungs, der industriellen Revolution und des raschen städtischen Wachstums, die vor allem im Deutschen Kaiserreich und in der [[Donaumonarchie]] (Österreich-Ungarn) stattfand\""}, {"kategorie": "", "text": "Die Gründerzeit war geprägt von einer intensiven Industrialisierung. Neue Technologien, wie die Dampfmaschine, Eisenbahn und Telegrafie, führten zu einem rasanten Wachstum in vielen Branchen, insbesondere im Maschinenbau, der Stahlindustrie und der chemischen Industrie"}, {"kategorie": "", "text": "Es entstand eine Vielzahl von Unternehmen, und es kam zu einer Gründungswelle neuer Aktiengesellschaften, daher der Name „Gründerzeit“"}, {"kategorie": "", "text": "Die wachsende Industrie zog viele Menschen in die Städte, was zu einer rasanten Urbanisierung führte. Viele Städte, insbesondere in Deutschland und Österreich-Ungarn, wuchsen erheblich"}, {"kategorie": "", "text": "Typisch für diese Zeit ist der Bau von sogenannten „Gründerzeitbauten“: Wohnhäuser und repräsentative Gebäude in dicht bebauten Stadtvierteln, oft mit aufwendigen Fassaden im Stil des [[Historismus]]. Diese Architektur ist durch eine Mischung aus verschiedenen Stilrichtungen (Neorenaissance, Neobarock, Neogotik etc.) gekennzeichnet."}]'::jsonb, ''),
  ('gruendazeitarchitektua', 'Gründazeitarchitektua', '', '', '', '', 'Gründerzeitarchitektur', '[{"kategorie": "allg.", "text": "\"Baustil, der während der [[Gründerzeit]] in Mitteleuropa, insbesondere im Deutschen Kaiserreich und in Österreich-Ungarn, vorherrschend war\""}, {"kategorie": "", "text": "Die Gründerzeit erstreckt sich ungefähr von den 1840er Jahren bis zum Ausbruch des Ersten Weltkriegs 1914. Diese Epoche war geprägt von einem intensiven wirtschaftlichen Aufschwung, starkem Bevölkerungswachstum und rascher Urbanisierung, was einen bedeutenden Bauboom und die Entwicklung charakteristischer Architekturmerkmale zur Folge hatte"}, {"kategorie": "", "text": "Die Gründerzeitarchitektur ist stark vom [[Historismus]] geprägt, einer Stilrichtung, die sich durch die Wiederbelebung und Kombination vergangener Baustile auszeichnet. Es wurden Elemente der Romanik, Gotik, Renaissance, des Barock und des [[Klassizismus]] miteinander vermischt"}, {"kategorie": "", "text": "Diese Stilvielfalt führte zu einer repräsentativen, oft sehr dekorativen Architektur, bei der die Fassaden reich verziert und mit architektonischen Details wie Säulen, Gesimsen, Erkern und Balustraden ausgestattet wurden"}, {"kategorie": "", "text": "Ein zentrales Merkmal der Gründerzeitarchitektur sind die prunkvollen Fassaden. Diese wurden oft symmetrisch gestaltet und waren reich mit Stuck, Ornamenten und anderen dekorativen Elementen versehen"}, {"kategorie": "", "text": "Typisch ist auch die horizontale Gliederung der Fassaden durch Gesimse und die vertikale Betonung durch Pilaster oder Lisenen. Die Fensterrahmungen waren oft aufwendig verziert, und es gab häufig Balkone und Erker"}, {"kategorie": "", "text": "Besonders in städtischen Mietshäusern gab es eine klare Trennung nach sozialem Status: Die wohlhabenderen Mieter wohnten in den repräsentativeren Geschossen, wie der [[Beletage]], während ärmere Bevölkerungsschichten in den weniger luxuriösen oberen Stockwerken oder im Dachgeschoss untergebracht waren."}]'::jsonb, ''),
  ('donaumonarchii', 'Donaumonarchii', '', '', '', '', 'Donaumonarchie', '[{"kategorie": "allg.", "text": "historischer Begriff, der sich auf das [[Kaisertum]] Österreich und später die [[Doppelmonarchie]] Österreich-Ungarn bezieht, ein Vielvölkerstaat in Mitteleuropa, der von 1804 bis 1918 existierte. Der Name leitet sich von der [[Donau]] ab, einem der wichtigsten Flüsse Europas, der durch viele Teile des Habsburgerreiches floss und daher symbolisch für die geografische Ausdehnung und kulturelle Vielfalt des Staates stand"}, {"kategorie": "", "text": "Die Donaumonarchie entstand aus den habsburgischen Erblanden und dem Heiligen Römischen Reich. Nach dem Untergang des Heiligen Römischen Reiches im Jahr 1806 und der Gründung des Kaisertums Österreich 1804 wurde das Habsburgerreich als Österreichisches Kaiserreich bezeichnet"}, {"kategorie": "", "text": "Im Jahr 1867 wurde durch den Ausgleich zwischen dem Kaisertum Österreich und dem Königreich Ungarn die Doppelmonarchie Österreich-Ungarn gegründet, die bis zum Ende des Ersten Weltkriegs 1918 bestand"}, {"kategorie": "", "text": "Die Donaumonarchie war ein komplexes Gebilde, das aus mehreren ethnischen und nationalen Gruppen bestand. Österreich-Ungarn war in zwei Hauptteile gegliedert: die österreichische Hälfte („Cisleithanien“) und die ungarische Hälfte („Transleithanien“), benannt nach den Flussufern der Leitha, die beide Territorien trennte"}, {"kategorie": "", "text": "Beide Teile hatten eigene Regierungen, Parlamente und Verwaltungssysteme, während die Außenpolitik, die Armee und die Finanzpolitik gemeinsam verwaltet wurden"}, {"kategorie": "", "text": "Die Donaumonarchie war bekannt für ihre kulturelle und ethnische Vielfalt. Sie umfasste zahlreiche Volksgruppen, darunter Deutsche, Ungarn, Tschechen, Slowaken, Polen, Ukrainer, Rumänen, Kroaten, Serben, Slowenen, Italiener und Juden. Die Gesellschaft war stark von den traditionellen Ständen geprägt, wobei der Adel eine bedeutende Rolle spielte, aber im 19. Jahrhundert begann auch eine starke Mittelschicht zu entstehen"}, {"kategorie": "", "text": "Die Donaumonarchie stand im 19. und frühen 20. Jahrhundert vor zahlreichen politischen Herausforderungen, insbesondere durch den Nationalismus der verschiedenen ethnischen Gruppen, der zu Spannungen und Konflikten innerhalb des Vielvölkerstaates führte"}, {"kategorie": "", "text": "Die Donaumonarchie endete 1918 mit dem Ende des Ersten Weltkriegs und dem Zusammenbruch Österreich-Ungarns. Das Reich zerfiel in mehrere unabhängige Nationalstaaten, darunter Österreich, Ungarn, die Tschechoslowakei, Jugoslawien und Polen."}]'::jsonb, ''),
  ('proodakej', 'Proodakej', '', '', '', '', 'Praterkai', '[{"kategorie": "allg.", "text": "\"Straße im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]), die entlang des Donaukanals verläuft\""}, {"kategorie": "", "text": "Der Name „Praterkai“ leitet sich vom nahegelegenen [[Wiener]] Prater ab, einem großen Park- und Erholungsgebiet, das eine zentrale Rolle im Freizeit- und Kulturleben Wiens spielt. Die Straße verbindet den [[Donaukanal]] mit dem Erholungsgebiet Prater und dient als wichtige Verkehrsverbindung im östlichen Teil Wiens"}, {"kategorie": "", "text": "Entlang des Praterkais befinden sich verschiedene Arten von Gebäuden, darunter Wohnhäuser, Bürogebäude und einige industrielle Einrichtungen. Die Nähe zum Prater und zum Donaukanal macht die Umgebung besonders attraktiv auch für Erholungs- und Freizeitaktivitäten"}, {"kategorie": "", "text": "Der Praterkai grenzt auch an das [[Messegelände]] mit mehreren großen Messe- und Veranstaltungshallen, die für internationale Messen und Veranstaltungen genutzt werden."}]'::jsonb, ''),
  ('ollahaeulignplotz', 'Ollahäulignplotz', '', '', '', '', 'Allerheiligenplatz', '[{"kategorie": "allg.", "text": "Platz im 20. Wiener Gemeindebezirk ([[Brigittenau]])"}, {"kategorie": "", "text": "Der Platz liegt im nördlichen Teil des Bezirks und ist ein zentraler Treffpunkt in einem vorwiegend von Wohngebieten geprägten Stadtteil. Er ist nach dem christlichen Fest Allerheiligen benannt, das am 1. November gefeiert wird"}, {"kategorie": "", "text": "Der Platz liegt im Herzen dieses Bezirks und ist von mehreren wichtigen Straßen umgeben, darunter die [[Allerheiligenstraße]] und die [[Pappenheimgasse]]"}, {"kategorie": "", "text": "Der Allerheiligenplatz ist ein sozialer Treffpunkt für die Bewohner des 20. Bezirks und bietet eine grüne Oase inmitten der städtischen Umgebung. Er ist ein beliebter Ort für Spaziergänge, zum Verweilen und für informelle Treffen."}]'::jsonb, ''),
  ('ollahaeulignschdrossn', 'Ollahäulignschdrossn', '', '', '', '', 'Allerheiligenstraße', '[{"kategorie": "allg.", "text": "Straße im 20. Wiener Gemeindebezirk ([[Brigittenau]]). Sie verläuft im nördlichen Teil des Bezirks und ist nach dem christlichen Fest Allerheiligen benannt, das am 1. November gefeiert wird"}, {"kategorie": "", "text": "Die Allerheiligenstraße verläuft durch einen dicht besiedelten Stadtteil, der zwischen dem [[Donaukanal]] und der [[Donau]] liegt. Sie erstreckt sich über mehrere Häuserblocks und verbindet wichtige Straßen und Plätze innerhalb des Bezirks, einschließlich des [[Allerheiligenplatzes]]. Die Straße beginnt im Bereich der [[Jägerstraße]] und zieht sich in nordöstlicher Richtung bis zur [[Adalbert-Stifter-Straße]]"}, {"kategorie": "", "text": "Die Allerheiligenstraße ist überwiegend von Wohnhäusern geprägt, die teilweise aus der [[Gründerzeit]] stammen. Diese Gebäude sind oft mehrstöckig und bieten Platz für Wohnungen sowie im Erdgeschoss gelegene Geschäfte und Dienstleistungsbetriebe"}, {"kategorie": "", "text": "Die Allerheiligenstraße ist eine typische Wohnstraße im 20. Bezirk, die das alltägliche Leben der Bewohner widerspiegelt. Sie bietet Zugang zu lokalen Geschäften, Märkten und sozialen Treffpunkten wie dem [[Allerheiligenplatz]], der an die Straße angrenzt."}]'::jsonb, ''),
  ('raxschdrossn', 'Raxschdrossn', '', '', '', '', 'Raxstraße', '[{"kategorie": "allg.", "text": "\"wichtige Verkehrsstraße im Süden von Wien, die durch den 10. Wiener Gemeindebezirk ([[Favoriten]]) verläuft\""}, {"kategorie": "", "text": "Die Straße ist nach der Rax benannt, einem beliebten Berg in den \"Wiener Alpen\", der sich an der Grenze zwischen Niederösterreich und der Steiermark befindet"}, {"kategorie": "", "text": "Die Raxstraße entwickelte sich im Zuge der Urbanisierung des 10. Bezirks, der ab dem späten 19. Jahrhundert ein starkes Bevölkerungswachstum erlebte"}, {"kategorie": "", "text": "Heute ist die Raxstraße eine wichtige innerstädtische Verkehrsverbindung im Bezirk [[Favoriten]], in deren Bereich sich sowohl ältere Gebäude als auch moderne Wohn- und Gewerbebauten befinden."}]'::jsonb, ''),
  ('jaegaschdrossn', 'Jägaschdrossn', '', '', '', '', 'Jägerstraße', '[{"kategorie": "allg.", "text": "\"bedeutende Verkehrsstraße im 20. Wiener Gemeindebezirk ([[Brigittenau]]). Sie verläuft in Nord-Süd-Richtung und ist eine der Hauptverkehrsachsen des Bezirks\""}, {"kategorie": "", "text": "Die Jägerstraße beginnt im Süden an der [[Friedensbrücke]], die über den [[Donaukanal]] führt und Brigittenau mit dem 9. Bezirk ([[Alsergrund]]) verbindet. Von dort verläuft sie in nördlicher Richtung durch Brigittenau und endet in der Nähe des [[Allerheiligenplatzes]], wo sie in die [[Adalbert-Stifter-Straße]] übergeht"}, {"kategorie": "", "text": "Die Jägerstraße hat ihren Namen wahrscheinlich von einer historischen Verbindung zur Jagd oder zu einer früheren Jagdroute, die durch dieses Gebiet führte. Im Laufe der Zeit entwickelte sich die Straße jedoch zu einer wichtigen städtischen Verkehrsachse"}, {"kategorie": "", "text": "Die Straße ist von einer Mischung aus Wohn- und Geschäftsgebäuden umgeben und spielt eine wesentliche Rolle im alltäglichen Leben der Anwohner. Mit ihrer historischen Bebauung und ihrer Bedeutung für den öffentlichen Nahverkehr ist die Jägerstraße ein charakteristischer und wichtiger Teil des Stadtbildes von Brigittenau."}]'::jsonb, ''),
  ('pappnheimgossn', 'Pappnheimgossn', '', '', '', '', 'Pappenheimgasse', '[{"kategorie": "allg.", "text": "\"Straße im 20. Wiener Gemeindebezirk ([[Brigittenau]]), die in Nord-Süd-Richtung verläuft und eine der zentralen Verbindungsstraßen in diesem dicht besiedelten Stadtteil ist\""}, {"kategorie": "", "text": "Die Straße ist nach der historischen Adelsfamilie Pappenheim benannt, die in der Geschichte des Heiligen Römischen Reiches eine bedeutende Rolle spielte, insbesondere durch Gottfried Heinrich zu Pappenheim, einen bekannten Feldherrn im Dreißigjährigen Krieg"}, {"kategorie": "", "text": "Die Pappenheimgasse beginnt im Süden an der [[Klosterneuburger]] Straße, einer wichtigen Hauptstraße des Bezirks, und verläuft in nordwestlicher Richtung. Sie endet in der Nähe der Adalbert-Stifter-Straße und Jägerstraße, wodurch sie eine wichtige Verbindung zwischen diesen Straßen und dem restlichen Bezirk darstellt"}, {"kategorie": "", "text": "Die Straße ist von einer Mischung aus Wohnhäusern und einigen Geschäftslokalen gesäumt. Die Gebäude entlang der Pappenheimgasse stammen größtenteils aus der [[Gründerzeit]] und dem frühen 20. Jahrhundert, was dem Straßenzug ein historisches und architektonisch interessantes Erscheinungsbild verleiht."}]'::jsonb, ''),
  ('seavitnviatl', 'Seavitnviatl', '', '', '', '', 'Servitenviertel', '[{"kategorie": "allg.", "text": "\"charmantes und historisch bedeutendes Stadtviertel im 9. Wiener Gemeindebezirk ([[Alsergrund]])\""}, {"kategorie": "", "text": "Es liegt zwischen der [[Rossauer]] Lände entlang des [[Donaukanals]] und der [[Alserbachstraße]] im Westen und gehört zu den beliebtesten Wohngegenden Wiens aufgrund seiner zentralen Lage, seines historischen Flairs und seiner lebendigen Atmosphäre"}, {"kategorie": "", "text": "Das Servitenviertel erstreckt sich über das Gebiet um die [[Servitengasse]] und die [[Porzellangasse]], die zu den Hauptstraßen des Viertels zählen. Es wird im Osten durch den Donaukanal und die Rossauer Lände begrenzt, während die Alserbachstraße und die [[Liechtensteinstraße]] im Westen eine natürliche Grenze bilden"}, {"kategorie": "", "text": "Das Viertel ist nach dem Servitenorden benannt, der 1639 in Wien ein Kloster gründete. Die [[Servitenkirche]], eine Barockkirche an der Servitengasse, ist das religiöse und historische Zentrum des Viertels. Die Kirche und das Kloster gehören zu den ältesten Gebäuden im Viertel und prägen bis heute dessen kulturellen und architektonischen Charakter"}, {"kategorie": "", "text": "Das Servitenviertel entwickelte sich ab dem 18. Jahrhundert zu einem begehrten Wohngebiet für wohlhabende Bürger und hat sich diesen Status bis heute bewahrt. Es bietet eine ruhige und dennoch zentrale Lage, was es besonders bei Familien, Akademikern und Künstlern beliebt macht"}, {"kategorie": "", "text": "Die vielen kleinen Boutiquen, Cafés, Restaurants und Lebensmittelgeschäfte, die oft in historischen Gebäuden untergebracht sind, tragen zur lebendigen und gleichzeitig entspannten Atmosphäre bei."}]'::jsonb, ''),
  ('seavitngossn', 'Seavitngossn', '', '', '', '', 'Servitengasse', '[{"kategorie": "allg.", "text": "malerische und historisch bedeutsame Straße im 9. Wiener Gemeindebezirk ([[Alsergrund]])"}, {"kategorie": "", "text": "Sie liegt im Herzen des [[Servitenviertels]], einem charmanten Stadtteil, der für seine gut erhaltene Architektur aus der [[Gründerzeit]] und seine lebendige, fast dörfliche Atmosphäre bekannt ist"}, {"kategorie": "", "text": "Sie verläuft in Nord-Süd-Richtung und verbindet die [[Porzellangasse]] im Norden mit der [[Liechtensteinstraße]] im Süden. Die Straße ist eine Fußgängerzone und bietet eine ruhige, entspannte Atmosphäre, die sich deutlich von den größeren, verkehrsreichen Straßen in der Umgebung abhebt"}, {"kategorie": "", "text": "Die Servitengasse ist nach dem Servitenorden benannt, der im 17. Jahrhundert in diesem Gebiet ein Kloster gründete. Der Name der Straße und des gesamten Viertels erinnert an die [[Servitenkirche]] und das zugehörige [[Servitenkloster]], die das religiöse und kulturelle Zentrum des Viertels darstellen"}, {"kategorie": "", "text": "Die Servitengasse ist von eleganten Gebäuden aus der Gründerzeit und dem Biedermeier gesäumt, die sorgfältig restauriert wurden und den historischen Charme der Straße bewahren. Die Architektur zeichnet sich durch ihre prächtigen Fassaden, hohen Decken und reich verzierten Eingangsbereiche aus"}, {"kategorie": "", "text": "Entlang der Servitengasse befinden sich zahlreiche kleine Geschäfte, Boutiquen, Cafés und Restaurants, die in den Erdgeschossen der Wohnhäuser untergebracht sind. Diese Mischung aus Wohnen und Gewerbe trägt zur lebendigen und doch gemütlichen Atmosphäre der Straße bei."}]'::jsonb, ''),
  ('seavitnkiachn', 'Seavitnkiachn', '', '', '', '', 'Servitenkirche', '[{"kategorie": "allg.", "text": "\"bedeutende barocke Kirche im 9. Wiener Gemeindebezirk ([[Alsergrund]]), auch \"Maria Verkündigung\" genannt"}, {"kategorie": "", "text": "Sie liegt im Herzen des [[Servitenviertels]] an der [[Servitengasse]] und ist das religiöse und architektonische Zentrum dieses charmanten Stadtteils. Die Kirche gehört zum Kloster der Serviten, einem katholischen Orden, der im 17. Jahrhundert nach Wien kam"}, {"kategorie": "", "text": "Die Servitenkirche wurde im Jahr 1638 von Mitgliedern des Servitenordens gegründet, die nach Wien gekommen waren, um sich hier niederzulassen. Die Kirche wurde 1670 geweiht und ist damit eine der ältesten Kirchen im 9. Bezirk. Sie ist ein bedeutendes Beispiel barocker Sakralarchitektur in Wien und wurde als Teil des [[Servitenklosters]] errichtet, das bis heute in Betrieb ist"}, {"kategorie": "", "text": "Die Servitenkirche ist ein barockes Bauwerk, das sich durch seine schlichte, aber elegante Fassade auszeichnet. Die Fassade ist symmetrisch gestaltet, mit einem zentralen Portal und zwei flankierenden Türmen"}, {"kategorie": "", "text": "Der Innenraum der Kirche ist reich an barocken Verzierungen und Kunstwerken. Die Ausstattung umfasst prachtvolle Altäre, Fresken und Skulpturen, die die religiösen Szenen und Heiligen des katholischen Glaubens darstellen. Besonders hervorzuheben ist das Hochaltarbild, das die Verkündigung Mariens darstellt, das zentrale Thema der Kirche. Der Altar und die Innenausstattung wurden von bekannten Künstlern der Barockzeit gestaltet"}, {"kategorie": "", "text": "Im Laufe der Jahrhunderte wurde die Servitenkirche mehrfach restauriert, um ihren historischen und architektonischen Wert zu erhalten. Diese Restaurierungen haben dazu beigetragen, dass die Kirche bis heute in gutem Zustand ist und weiterhin als wichtiger Sakralbau genutzt wird."}]'::jsonb, ''),
  ('seavitnkloosta', 'Seavitnkloosta', '', '', '', '', 'Servitenkloster', '[{"kategorie": "allg.", "text": "\"historisches Kloster des Servitenordens (Ordo Servorum Mariae, OSM) im 9. Wiener Gemeindebezirk ([[Alsergrund]])\""}, {"kategorie": "", "text": "Es befindet sich im Herzen des [[Servitenviertels]], direkt an der [[Servitengasse]], neben der [[Servitenkirche]], die Teil des Klosterkomplexes ist"}, {"kategorie": "", "text": "Das Servitenkloster wurde im Jahr 1638 gegründet, als Mitglieder des Servitenordens nach Wien kamen. Der Orden, der im 13. Jahrhundert in Florenz gegründet wurde, widmete sich der Verehrung der Jungfrau Maria und der Seelsorge"}, {"kategorie": "", "text": "Das Klostergebäude ist ein barocker Bau, der in mehreren Bauphasen im 17. und 18. Jahrhundert errichtet wurde. Es zeichnet sich durch eine schlichte, aber solide Architektur aus, die für klösterliche Bauten dieser Zeit typisch ist"}, {"kategorie": "", "text": "Die Klosteranlage umfasst neben der Kirche auch Wohn- und Gemeinschaftsräume für die Ordensmitglieder, einen Innenhof und verschiedene Funktionsgebäude, die für das klösterliche Leben notwendig sind"}, {"kategorie": "", "text": "Das Servitenkloster wird weiterhin von den Serviten genutzt und gepflegt. Es ist ein lebendiges Kloster, in dem das spirituelle Leben des Ordens fortgesetzt wird. Die Ordensmitglieder sind in der Seelsorge tätig und bieten spirituelle Begleitung und religiöse Dienste an."}]'::jsonb, ''),
  ('michlbaeuan', 'Michlbäuan', '', '', '', '', 'Michelbeuern', '[{"kategorie": "allg.", "text": "\"historisches Gebiet im 9. Wiener Gemeindebezirk ([[Alsergrund]])\""}, {"kategorie": "", "text": "Ursprünglich handelte es sich um eine eigenständige kleine Ortschaft beziehungsweise Siedlung, die im Laufe der Zeit in das Stadtgebiet von Wien eingegliedert wurde"}, {"kategorie": "", "text": "Michelbeuern liegt im südlichen Teil des 9. Wiener Gemeindebezirks, westlich des [[Gürtel]], und grenzt an den Bezirk [[Hernals]] im Westen und an den Bereich um das [[Allgemeine]] Krankenhaus ([[AKH]]) im Osten"}, {"kategorie": "", "text": "Michelbeuern geht auf eine frühere bäuerliche Siedlung zurück, die vermutlich bereits im Mittelalter existierte. Der Name „Michelbeuern“ leitet sich wahrscheinlich von einem Bauernhof oder einem Gutshof ab, der ursprünglich dem Heiligen Michael geweiht war"}, {"kategorie": "", "text": "Im Laufe des 19. und 20. Jahrhunderts wurde Michelbeuern zunehmend urbanisiert und in das Stadtgebiet von Wien integriert. Der heutige Verkehrsknotenpunkt „Michelbeuern-AKH“ ist eine bedeutende U-Bahn-Station der Linie U6 und liegt in unmittelbarer Nähe zum Allgemeinen Krankenhaus Wien (AKH), einem der größten Krankenhäuser Europas."}]'::jsonb, ''),
  ('oisabochschdrossn', 'Oisabochschdrossn', '', '', '', '', 'Alserbachstraße', '[{"kategorie": "allg.", "text": "\"bedeutende Verkehrsstraße im 9. Wiener Gemeindebezirk ([[Alsergrund]])\""}, {"kategorie": "", "text": "Sie erstreckt sich von der [[Rossauer]] Lände im Osten, nahe dem [[Donaukanal]], bis zur [[Liechtensteinstraße]] im Westen. Sie verläuft dabei durch das Herz des 9. Bezirks und kreuzt unter anderem die [[Porzellangasse]] und die [[Nußdorfer]] Straße, zwei weitere bedeutende Straßen im Bezirk, was ihr eine wichtige Funktion als Verkehrsachse verleiht"}, {"kategorie": "", "text": "Die Alserbachstraße ist nach dem Alserbach benannt, einem Fluss, der einst durch das Gebiet floss. Der Alserbach wurde im 19. Jahrhundert größtenteils kanalisiert und unterirdisch verlegt, doch sein Name lebt in der Benennung der Straße weiter"}, {"kategorie": "", "text": "Die Alserbachstraße ist ein lebendiger Teil des Alsergrunds und trägt zur kulturellen Vielfalt und sozialen Dynamik des Bezirks bei. Die Mischung aus historischen Gebäuden, modernen Geschäften und kulturellen Einrichtungen macht die Straße zu einem beliebten Wohn- und Aufenthaltsort."}]'::jsonb, ''),
  ('woinschdeinstrossn', 'Woinschdeinstrossn', '', '', '', '', 'Wallensteinstraße', '[{"kategorie": "allg.", "text": "\"bedeutende Verkehrsstraße im 20. Wiener Gemeindebezirk ([[Brigittenau]]). Sie verläuft in Ost-West-Richtung und ist eine der Hauptverkehrsachsen des Bezirks\""}, {"kategorie": "", "text": "Die Wallensteinstraße erstreckt sich von der [[Augartenbrücke]] im Osten, wo sie den [[Donaukanal]] und den [[Augarten]] tangiert, bis zur Grenze des 20. Bezirks im Westen, in der Nähe des [[Sachsenplatzes]]"}, {"kategorie": "", "text": "Die Straße verläuft parallel zur [[Jägerstraße]], einer weiteren wichtigen Verkehrsader in Brigittenau, und kreuzt mehrere bedeutende Straßen und Plätze im Bezirk, darunter den [[Gaußplatz]] und den [[Wallensteinplatz]]"}, {"kategorie": "", "text": "Die Wallensteinstraße wurde nach Albrecht von Wallenstein benannt, einem einflussreichen Feldherrn des Dreißigjährigen Krieges, der für seine militärischen Erfolge und seine Rolle in der europäischen Geschichte bekannt ist"}, {"kategorie": "", "text": "Die Straße entwickelte sich im Zuge der Urbanisierung Wiens im 19. Jahrhundert zu einer der Hauptstraßen von Brigittenau und ist seitdem eine wichtige Verkehrsader und Lebensader des Bezirks."}]'::jsonb, ''),
  ('woinschdeinplotz', 'Woinschdeinplotz', '', '', '', '', 'Wallensteinplatz', '[{"kategorie": "allg.", "text": "zentraler Platz im 20. Wiener Gemeindebezirk ([[Brigittenau]])"}, {"kategorie": "", "text": "Der Wallensteinplatz befindet sich im Herzen des 20. Bezirks, an der Kreuzung der [[Wallensteinstraße]] mit der [[Klosterneuburger]] Straße. Diese Lage macht ihn zu einem zentralen Punkt in der Verkehrs- und Stadtplanung des Bezirks"}, {"kategorie": "", "text": "Der Wallensteinplatz ist nach Albrecht von Wallenstein benannt, einem bedeutenden Feldherrn des Dreißigjährigen Krieges. Die Benennung des Platzes und der ihn durchquerenden Wallensteinstraße erfolgte im Zuge der Stadterweiterung Wiens im 19. Jahrhundert, als Brigittenau zu einem dicht besiedelten Stadtteil ausgebaut wurde"}, {"kategorie": "", "text": "Der Platz ist von historischen Wohn- und Geschäftshäusern umgeben und bietet durch seine Grünflächen und Sitzgelegenheiten einen Ort der Entspannung. Er ist auch ein beliebter Ort für kleinere Veranstaltungen und Märkte, die das kulturelle Leben im Bezirk bereichern."}]'::jsonb, ''),
  ('antonsplotz', 'Antonsplotz', '', '', '', '', 'Antonsplatz', '[{"kategorie": "allg.", "text": "\"Platz im historischen Zentrum des 10. Wiener Gemeindebezirks ([[Favoriten]])\""}, {"kategorie": "", "text": "Der Platz wurde nach dem heiligen Antonius von Padua benannt, einem beliebten katholischen Heiligen, der auch Namensgeber für die nahegelegene [[Antonskirche]] ist"}, {"kategorie": "", "text": "Der Antonsplatz ist ein klassischer Wiener Stadtplatz, der von Bäumen gesäumt und mit Sitzbänken ausgestattet ist, die den Anwohnern und Besuchern einen Ort zum Verweilen bieten. Der Platz ist relativ klein, aber durch seine zentrale Lage und seine historische Bedeutung ein wichtiger Bestandteil des Viertels"}, {"kategorie": "", "text": "Die [[Antonskirche]], die sich in unmittelbarer Nähe des Platzes befindet, ist ein markantes Gebäude, das den Platz architektonisch dominiert und dem Platz seinen Namen gibt. Die Kirche ist ein bedeutendes Beispiel für neogotische Architektur in Wien."}]'::jsonb, ''),
  ('antonskiachn', 'Antonskiachn', '', '', '', '', 'Antonskirche', '[{"kategorie": "allg.", "text": "\"bedeutende römisch-katholische Kirche im 10. Wiener Gemeindebezirk ([[Favoriten]]), offiziell \"Kirche St. Anton von Padua\""}, {"kategorie": "", "text": "Sie ist nach dem heiligen Antonius von Padua benannt und befindet sich am [[Antonsplatz]], im Herzen des historischen Favoriten"}, {"kategorie": "", "text": "Die Antonskirche wurde zwischen 1896 und 1901 im neogotischen Stil erbaut, einer Architekturströmung, die im 19. Jahrhundert populär war und sich durch die Wiederbelebung gotischer Bauformen auszeichnete. Die Kirche wurde nach den Plänen des Architekten Franz von Neumann errichtet"}, {"kategorie": "", "text": "Die Kirche hat eine beeindruckende Fassade mit charakteristischen neogotischen Elementen wie Spitzbogenfenstern, [[Fialen]] und einem hohen Kirchturm, der das Stadtbild von Favoriten prägt. Der Innenraum der Kirche ist reich an kunstvollen Details, darunter bunte Glasfenster, Altäre und Figuren, die den gotischen Stil unterstreichen."}]'::jsonb, ''),
  ('gaussplotz', 'Gaussplotz', '', '', '', '', 'Gaußplatz', '[{"kategorie": "allg.", "text": "\"zentraler Platz im 20. Wiener Gemeindebezirk ([[Brigittenau]])\""}, {"kategorie": "", "text": "Er ist nach dem berühmten deutschen Mathematiker und Physiker Carl Friedrich Gauß benannt und bildet einen wichtigen Verkehrsknotenpunkt sowie einen sozialen und kulturellen Treffpunkt im Bezirk"}, {"kategorie": "", "text": "Der Platz liegt in einem dicht besiedelten, urbanen Gebiet und ist von Wohn- und Geschäftshäusern umgeben. Er befindet sich an der Kreuzung von mehreren bedeutenden Straßen, darunter die [[Wallensteinstraße]], [[Klosterneuburger]] Straße und [[Jägerstraße]]"}, {"kategorie": "", "text": "Der Gaußplatz wurde im Zuge der städtebaulichen Entwicklung von Brigittenau im 19. Jahrhundert angelegt und nach Carl Friedrich Gauß benannt, einem der bedeutendsten Wissenschaftler seiner Zeit, der vor allem für seine Beiträge zur Mathematik und Physik bekannt ist"}, {"kategorie": "", "text": "Mit seiner Gestaltung als öffentlicher Raum und seiner Rolle als sozialer Treffpunkt ist der Gaußplatz ein wichtiger Bestandteil des urbanen Lebens und der kulturellen Dynamik in Brigittenau."}]'::jsonb, ''),
  ('saxnplotz', 'Saxnplotz', '', '', '', '', 'Sachsenplatz', '[{"kategorie": "allg.", "text": "\"zentraler Platz im 20. Wiener Gemeindebezirk ([[Brigittenau]])\""}, {"kategorie": "", "text": "Der Sachsenplatz befindet sich im westlichen Teil des 20. Bezirks, in der Nähe der Grenze zum 9. Bezirk ([[Alsergrund]]). Er liegt an der Kreuzung der [[Wallensteinstraße]] und der [[Klosterneuburger]] Straße, zwei wichtigen Verkehrsachsen des Bezirks"}, {"kategorie": "", "text": "Der Sachsenplatz entstand im Zuge der Urbanisierung Wiens im 19. Jahrhundert. Die Benennung des Platzes nach dem deutschen Bundesland Sachsen spiegelt die damalige Praxis wider, öffentliche Plätze nach geografischen oder historischen Begriffen zu benennen"}, {"kategorie": "", "text": "Der Platz ist von Wohn- und Geschäftshäusern aus der [[Gründerzeit]] umgeben und bietet durch seine Grünflächen und Sitzmöglichkeiten einen Ort der Erholung im städtischen Umfeld."}]'::jsonb, ''),
  ('rotunde', 'Rotunde', '', '', '', '', 'Rotunde', '[{"kategorie": "allg.", "text": "\"beeindruckendes und bedeutendes Bauwerk in Wien, das speziell für die Weltausstellung 1873 errichtet wurde\""}, {"kategorie": "", "text": "Sie befand sich im [[Prater]], einem großen Erholungsgebiet im 2. Wiener Gemeindebezirk, Leopoldstadt. Die Rotunde war eines der größten Kuppelbauwerke ihrer Zeit und diente nach der Weltausstellung als multifunktionaler Veranstaltungsort für Messen, Ausstellungen und andere Großveranstaltungen"}, {"kategorie": "", "text": "Die Rotunde wurde von dem Architekten Karl von Hasenauer entworfen und war ein monumentales Bauwerk mit einem Durchmesser von 108 Metern und einer Kuppelhöhe von etwa 84 Metern. Sie war eines der größten Gebäude ihrer Art und ein herausragendes Beispiel für die Architektur des 19. Jahrhunderts und ein Symbol der wirtschaftlichen und kulturellen Blütezeit Wiens im späten 19. und frühen 20. Jahrhundert. Sie wird oft in historischen Aufzeichnungenerwähnt und ist ein wichtiger Teil des kulturellen Erbes der Stadt"}, {"kategorie": "", "text": "Trotz ihrer imposanten Größe und Bedeutung wurde die Rotunde im Laufe der Zeit zunehmend durch moderne Veranstaltungsorte ersetzt. Dennoch blieb sie ein wichtiges Wahrzeichen Wiens, bis sie 1937 durch einen Brand zerstört wurde. Nach dem Brand wurde die Rotunde nicht wieder aufgebaut. Der Standort im Prater, an dem sie einst stand, ist heute Teil des [[Wiener]] Messegeländes."}]'::jsonb, ''),
  ('radetzkyschdrossn', 'Radetzkyschdrossn', '', '', '', '', 'Radetzkystraße', '[{"kategorie": "allg.", "text": "\"bedeutende Verkehrsstraße im 3. Wiener Gemeindebezirk ([[Landstraße]])\":  2. Sie beginnt im Norden an der [[Uraniastraße]] in der Nähe des [[Donaukanals]] und verläuft in südlicher Richtung bis zum [[Radetzkyplatz]], einem zentralen Platz im 3. Bezirk. Von dort setzt sie sich in Richtung Süden fort und endet schließlich an der [[Landstraßer]] Hauptstraße, einer weiteren wichtigen Verkehrsachse des Bezirks"}, {"kategorie": "", "text": "Sie ist nach dem berühmten österreichischen Feldmarschall Joseph Wenzel Graf Radetzky von Radetz (1766–1858) benannt, der für seine militärischen Erfolge im Dienste der [[Habsburger]] während des Dreißigjährigen Krieges bekannt ist"}, {"kategorie": "", "text": "Die Radetzkystraße ist von einer Mischung aus historischen Gebäuden und moderneren Bauten umgeben. Viele der Gebäude stammen aus der [[Gründerzeit]] und dem frühen 20. Jahrhundert, was der Straße ein elegantes, urbanes Erscheinungsbild verleiht."}]'::jsonb, ''),
  ('uraniaschdrossn', 'Uraniaschdrossn', '', '', '', '', 'Uraniastraße', '[{"kategorie": "allg.", "text": "\"bedeutende Verkehrsstraße, welche die Grenze zwischen dem 1. und dem 3. Wiener Gemeindebezirk ([[Innere Stadt]] bzw. [[Landstraße]]) bildet\""}, {"kategorie": "", "text": "Die Uraniastraße beginnt am [[Schottenring]] im 1. Bezirk und führt in südöstlicher Richtung entlang des [[Donaukanals]] bis zur [[Aspernbrücke]], wo sie in die [[Weißgerberlände]] übergeht"}, {"kategorie": "", "text": "Entlang der Uraniastraße befinden sich eine Reihe von bemerkenswerten Gebäuden, darunter die [[Urania]], ein Gebäude, das als Volksbildungshaus mit Sternwarte und Kino dient und 1910 nach den Plänen von Max Fabiani errichtet wurde. Dieses markante Bauwerk prägt das Erscheinungsbild der Straße und ist ein wichtiger kultureller Anziehungspunkt"}, {"kategorie": "", "text": "Die Umgebung der Uraniastraße ist von einer Mischung aus historischen und modernen Gebäuden geprägt, darunter Büros, Restaurants, Hotels und Wohnhäuser. Die Nähe zum Donaukanal bietet auch Erholungsmöglichkeiten und eine attraktive Umgebung für Spaziergänger."}]'::jsonb, ''),
  ('weissgeabalaende', 'Weissgeabalände', '', '', '', '', 'Weißgerberlände', '[{"kategorie": "allg.", "text": "\"bedeutende Verkehrsstraße im 3. Wiener Gemeindebezirk ([[Landstraße]]), die entlang des [[Donaukanals]] in nordwestlicher Richtung verläuft\""}, {"kategorie": "", "text": "Sie beginnt in der Nähe des Stadtzentrums, wo sie an die [[Uraniastraße]] anschließt, und führt weiter bis zur [[Erdberger]] Lände im Südosten"}, {"kategorie": "", "text": "Der Name \"Weißgerberlände\" verweist auf das historische Handwerk der Weißgerber, die in dieser Gegend tätig waren. Weißgerber waren spezialisiert auf die Bearbeitung von Leder, insbesondere auf das Gerben von Häuten, das im 18. und 19. Jahrhundert in Wien von großer wirtschaftlicher Bedeutung war"}, {"kategorie": "", "text": "Sie verbindet das Stadtzentrum mit den südöstlichen Bezirken Wiens und ist von einer Vielzahl von Gebäuden umgeben, die das industrielle Erbe des Gebiets widerspiegeln, sowie auch von Wohnhäusern, die größtenteils aus dem späten 19. und frühen 20. Jahrhundert stammen, aber auch von modernen Wohn- und Bürogebäuden."}]'::jsonb, ''),
  ('radetzkybruckn', 'Radetzkybruckn', '', '', '', '', 'Radetzkybrücke', '[{"kategorie": "allg.", "text": "\"wichtige Straßenbrücke in Wien, die den [[Donaukanal]] überspannt und die [[Radetzkystraße]] im 3. Wiener Gemeindebezirk ([[Landstraße]]) mit der [[Oberen]] Donaustraße und der [[Praterstraße]] im 2. Bezirk ([[Leopoldstadt]]) verbindet\""}, {"kategorie": "", "text": "Ihre zentrale Lage macht sie zu einer wichtigen Verkehrsverbindung, die täglich von einer großen Anzahl von Fahrzeugen, Fußgängern und Radfahrern genutzt wird. Die Brücke liegt nahe dem historischen [[Prater]] und dem [[Praterstern]], einem wichtigen Verkehrsknotenpunkt in Wien"}, {"kategorie": "", "text": "Die Radetzkybrücke wurde nach dem berühmten österreichischen Feldmarschall Joseph Wenzel Graf Radetzky von Radetz benannt, einer der prominentesten Militärfiguren des [[Habsburgerreiches]] im 19. Jahrhundert. Die Brücke erhielt ihren Namen, um die Verdienste Radetzkys, insbesondere seine militärischen Erfolge, zu würdigen"}, {"kategorie": "", "text": "Die erste Radetzkybrücke wurde in der zweiten Hälfte des 19. Jahrhunderts errichtet, als Wien begann, den Donaukanal stärker in die städtische Infrastruktur einzubinden. Ursprünglich handelte es sich um eine eiserne Konstruktion, die jedoch im Laufe der Jahre mehrfach erneuert wurde, um den steigenden Anforderungen des Verkehrs gerecht zu werden."}]'::jsonb, ''),
  ('augoatnbruckn', 'Augoatnbruckn', '', '', '', '', 'Augartenbrücke', '[{"kategorie": "allg.", "text": "Straßenbrücke in Wien, die den Donaukanal überspannt und die [[Rossauer]] Lände im 9. Bezirk ([[Alsergrund]]) mit der [[Oberen]] Donaustraße im 2. Bezirk ([[Leopoldstadt]]) verbindet"}, {"kategorie": "", "text": "Ihre Lage in der Nähe des historischen [[Augartens]], einem der ältesten Barockgärten Wiens, verleiht der Brücke ihren Namen"}, {"kategorie": "", "text": "Die Augartenbrücke wurde erstmals im 19. Jahrhundert errichtet, als Wien begann, seine Infrastruktur zu modernisieren und die Verkehrsverbindungen über den Donaukanal auszubauen. Die Brücke spielte eine wichtige Rolle bei der Erschließung der Leopoldstadt und der Anbindung dieses Bezirks an die zentraleren Teile Wiens"}, {"kategorie": "", "text": "Die heutige Augartenbrücke ist eine moderne Stahlbetonbrücke, die nach dem Zweiten Weltkrieg errichtet wurde. Sie ist funktional und schlicht gestaltet, was typisch für die Brückenarchitektur der Nachkriegszeit ist."}]'::jsonb, ''),
  ('mariinbruckn', 'Mariinbruckn', '', '', '', '', 'Marienbrücke', '[{"kategorie": "allg.", "text": "\"Straßenbrücke in Wien, die den [[Donaukanal]] überspannt und eine Verbindung zwischen dem 1. Wiener Gemeindebezirk ([[Innere]] Stadt) und dem 2. Bezirk ([[Leopoldstadt]]) herstellt. Sie ist eine der zentral gelegenen Brücken über den Donaukanal und spielt eine wichtige Rolle im städtischen Verkehrssystem\""}, {"kategorie": "", "text": "Die Marienbrücke hat ihren Namen von der Mariensäule, die sich einst in ihrer Nähe befand. Die Brücke wurde ursprünglich im 19. Jahrhundert erbaut und war Teil der Bemühungen, die Verkehrsverbindungen in der schnell wachsenden Stadt Wien zu verbessern. Während des Zweiten Weltkriegs wurde die ursprüngliche Brücke zerstört und später im Zuge des Wiederaufbaus erneuert"}, {"kategorie": "", "text": "Die heutige Marienbrücke ist das Ergebnis mehrerer Umbauten und Modernisierungen, die sicherstellen sollten, dass sie den Anforderungen des modernen Stadtverkehrs gerecht wird. Ihr Name hat sich über die Jahre hinweg erhalten und erinnert an die historische Bedeutung der Brücke und ihrer Umgebung."}]'::jsonb, ''),
  ('schwednbruckn', 'Schwednbruckn', '', '', '', '', 'Schwedenbrücke', '[{"kategorie": "allg.", "text": "\"bedeutende Straßen- und Fußgängerbrücke, die den [[Donaukanal]] in Wien überspannt und den 1. Wiener Gemeindebezirk ([[Innere]] Stadt) mit dem 2. Bezirk ([[Leopoldstadt]]) verbindet. Sie gehört zu den zentralen Brücken über den Donaukanal und hat sowohl verkehrstechnisch als auch historisch eine wichtige Rolle in der Stadt\""}, {"kategorie": "", "text": "Die Schwedenbrücke liegt im Herzen von Wien und verbindet die [[Schwedenplatz-Region]] im 1. Bezirk mit der [[Taborstraße]] im 2. Bezirk"}, {"kategorie": "hist.", "text": "Der Name \"Schwedenbrücke\" geht auf die Zeit nach dem Ersten Weltkrieg zurück, als Schweden im Zuge der humanitären Hilfe für das notleidende Österreich eine besondere Rolle spielte. Die Brücke wurde 1926 als Anerkennung für die Unterstützung Schwedens benannt, insbesondere für die schwedische Hilfe in Form von Lebensmittellieferungen und medizinischer Versorgung während der Nachkriegsjahre"}, {"kategorie": "", "text": "Die ursprüngliche Brücke an dieser Stelle war eine Holzbrücke, die bereits im 17. Jahrhundert existierte und im Laufe der Jahrhunderte mehrfach ersetzt und modernisiert wurde. Die heutige Schwedenbrücke wurde nach dem Zweiten Weltkrieg neu erbaut und trägt den Namen seit der Umbenennung 1926"}, {"kategorie": "", "text": "Heute ist die Schwedenbrücke ein unverzichtbarer Bestandteil des Wiener Stadtverkehrs. Sie wird täglich von Tausenden von Fahrzeugen, Fußgängern und Radfahrern genutzt. Die Brücke hat sich als zentraler Verkehrsweg etabliert, der sowohl für den Alltag als auch für den Zugang zu touristischen Attraktionen in Wien von Bedeutung ist."}]'::jsonb, ''),
  ('rotundnbruckn', 'Rotundnbruckn', '', '', '', '', 'Rotundenbrücke', '[{"kategorie": "allg.", "text": "\"Straßenbrücke, die den [[Donaukanal]] in Wien überspannt und den 2. Wiener Gemeindebezirk ([[Leopoldstadt]]) mit dem 3. Bezirk ([[Landstraße]]) verbindet\""}, {"kategorie": "", "text": "Die Brücke liegt in der Nähe des [[Wiener]] Praters, einem großen öffentlichen Park, und führt direkt zum [[Messegelände]] und zum Viertel um den [[Bahnhof]] Wien Mitte. Diese Lage macht sie zu einer wichtigen Verkehrsverbindung sowohl für den Individualverkehr als auch für Fußgänger und Radfahrer"}, {"kategorie": "", "text": "Die Rotundenbrücke wurde nach der nahegelegenen [[Rotunde]] benannt, einem monumentalen Gebäude, das für die Weltausstellung 1873 in Wien errichtet wurde. Die ursprüngliche Rotundenbrücke wurde im späten 19. Jahrhundert erbaut, um die Verbindung zwischen dem Prater und den neuen Stadtteilen im Süden des Donaukanals zu verbessern. Sie diente der besseren Erreichbarkeit des Messegeländes und anderer wichtiger Einrichtungen"}, {"kategorie": "", "text": "Heute ist die Rotundenbrücke nicht nur eine funktionale Verkehrsbrücke, sondern auch ein wichtiger Teil der historischen und kulturellen Landschaft Wiens. Sie verbindet zentrale Stadtteile und spielt eine bedeutende Rolle im täglichen Leben der Stadt."}]'::jsonb, ''),
  ('aspanbruckn', 'Aspanbruckn', '', '', '', '', 'Aspernbrücke', '[{"kategorie": "allg.", "text": "bedeutende Straßenbrücke, die den [[Donaukanal]] in Wien überspannt und den 1. Wiener Gemeindebezirk ([[Innere]] Stadt) mit dem 2. Bezirk ([[Leopoldstadt]]) verbindet"}, {"kategorie": "", "text": "Die Aspernbrücke wurde ursprünglich im Jahr 1864 erbaut und war Teil des Bestrebens, die Verkehrsverbindungen über den Donaukanal zu verbessern, der zu jener Zeit eine wichtige Rolle als Wasserweg spielte. Benannt wurde die Brücke nach der [[Schlacht]] bei Aspern, einem entscheidenden Gefecht während der Napoleonischen Kriege im Jahr 1809, bei dem die österreichischen Truppen unter Erzherzog Karl die französischen Truppen unter Napoleon besiegten. Dieser Name symbolisiert die patriotische Erinnerung an diesen militärischen Erfolg"}, {"kategorie": "", "text": "Nach dem Zweiten Weltkrieg, während dessen die Brücke schwer beschädigt wurde, erfolgte ein Wiederaufbau. Die heutige Konstruktion stammt aus den 1950er Jahren"}, {"kategorie": "", "text": "Die Brücke hat ihren historischen und symbolischen Charakter bewahrt, wobei sie gleichzeitig auch den modernen Anforderungen des Verkehrs gerecht wird."}]'::jsonb, ''),
  ('friidnsbruckn', 'Friidnsbruckn', '', '', '', '', 'Friedensbrücke', '[{"kategorie": "allg.", "text": "bedeutende Straßen- und Eisenbahnbrücke in Wien, die den [[Donaukanal]] im 9. Wiener Gemeindebezirk ([[Alsergrund]]) überspannt und diesen Bezirk mit dem 20. Bezirk ([[Brigittenau]]) verbindet. Sie ist eine wichtige Verkehrsverbindung und spielt eine zentrale Rolle sowohl im städtischen Verkehr als auch im öffentlichen Nahverkehr Wiens"}, {"kategorie": "", "text": "Die Friedensbrücke liegt im Norden des Wiener Stadtzentrums und verbindet den Alsergrund auf der linken Seite des Donaukanals mit der Brigittenau auf der rechten Seite. Sie führt die Verkehrsachse [[Alserbachstraße]] im 9. Bezirk über den Donaukanal und mündet in die [[Wallensteinstraße]] im 20. Bezirk"}, {"kategorie": "", "text": "Die erste Brücke an dieser Stelle wurde 1876 als \"Brigittenauer Brücke\" errichtet, um den wachsenden Verkehr zwischen den beiden Bezirken zu bewältigen. Diese ursprüngliche Brücke war eine Eisenkonstruktion und diente vor allem dem Fußgänger- und Pferdeverkehr"}, {"kategorie": "", "text": "Die heutige Friedensbrücke wurde nach dem Ersten Weltkrieg geplant und in den Jahren 1924 bis 1926 erbaut. Sie wurde 1926 feierlich eröffnet und erhielt ihren Namen als Ausdruck des Friedenswillens nach den Schrecken des Ersten Weltkriegs. Die Brücke wurde als Symbol für den Wunsch nach dauerhafter Friedenssicherung und Versöhnung in Europa benannt."}]'::jsonb, ''),
  ('franznsbruckn', 'Franznsbruckn', '', '', '', '', 'Franzensbrücke', '[{"kategorie": "allg.", "text": "wichtige Straßen- und Fußgängerbrücke, die den [[Donaukanal]] in Wien überspannt und den 2. Wiener Gemeindebezirk ([[Leopoldstadt]]) mit dem 3. Bezirk ([[Landstraße]]) verbindet"}, {"kategorie": "", "text": "Die Franzensbrücke hat eine lange Geschichte, die bis ins 19. Jahrhundert zurückreicht. Der Name der Brücke geht auf [[Kaiser]] Franz I. von Österreich zurück, nach dem sie benannt ist. Die ursprüngliche Brücke an dieser Stelle wurde im Jahr 1835 errichtet und war Teil der Bemühungen, die Verkehrsverbindungen in der wachsenden Stadt Wien zu verbessern"}, {"kategorie": "", "text": "Die Franzensbrücke verläuft über den [[Donaukanal]] und verbindet die Franzensbrückengasse im 2. Bezirk mit der Erdbergstraße im 3. Bezirk. Sie ist eine wichtige Verbindung für den Individualverkehr, den öffentlichen Verkehr sowie für Fußgänger und Radfahrer. Die Brücke befindet sich nahe dem [[Praterstern]], einem bedeutenden Verkehrsknotenpunkt in Wien, und ermöglicht eine direkte Verbindung zwischen diesen zentralen Bereichen der Stadt."}]'::jsonb, ''),
  ('soiztoabruckn', 'Soiztoabruckn', '', '', '', '', 'Salztorbrücke', '[{"kategorie": "allg.", "text": "\"wichtige Straßenbrücke, die den Donaukanal in Wien überspannt und den 1. Wiener Gemeindebezirk ([[Innere]] Stadt) mit dem 2. Bezirk ([[Leopoldstadt]]) verbindet. Sie ist eine der zahlreichen Brücken über den Donaukanal und spielt eine zentrale Rolle in der Verkehrsführung zwischen diesen beiden Stadtteilen\""}, {"kategorie": "", "text": "Die Salztorbrücke befindet sich in unmittelbarer Nähe des historischen Zentrums von Wien. Sie verbindet die [[Salztorgasse]] im 1. Bezirk mit der [[Oberen]] Donaustraße im 2. Bezirk"}, {"kategorie": "hist.", "text": "Der Name \"Salztorbrücke\" leitet sich vom ehemaligen Salztor ab, einem Stadttor der alten Wiener Stadtmauer, das in der Nähe der heutigen Brücke lag. Dieses Tor war ein wichtiger Punkt für den Handel mit Salz, einem wertvollen Gut in früheren Zeiten, das der Brücke und der umgebenden Gegend ihren Namen gab"}, {"kategorie": "", "text": "Die ursprüngliche Brücke an dieser Stelle wurde im 19. Jahrhundert errichtet, als Wien begann, seine Infrastruktur zu modernisieren und den Donaukanal stärker in die Stadtentwicklung einzubeziehen. Im Laufe der Jahre wurde die Brücke mehrmals erneuert und an die wachsenden Verkehrsanforderungen angepasst"}, {"kategorie": "", "text": "Die heutige Salztorbrücke ist eine moderne Stahlbetonbrücke, die für den gemischten Verkehr (Autos, Fußgänger, Radfahrer) ausgelegt ist. Sie ist schlicht und funktional gestaltet, was ihrem primären Zweck als Verkehrsbrücke entspricht. Die Brücke bietet zudem einen guten Blick auf den Donaukanal und die umliegenden Stadtteile."}]'::jsonb, ''),
  ('laabeagschdrossn', 'Laabeagschdrossn', '', '', '', '', 'Laaerbergstraße', '[{"kategorie": "allg.", "text": "bedeutende Verkehrsstraße im 10. Wiener Gemeindebezirk ([[Favoriten]])"}, {"kategorie": "", "text": "Sie beginnt im nördlichen Teil bei der [[Favoritenstraße]], einer der Hauptverkehrsadern im 10. Bezirk. Von dort aus verläuft sie in südöstlicher Richtung und führt durch den Bezirk Favoriten bis zur Stadtgrenze Wiens"}, {"kategorie": "", "text": "Die Laaerbergstraße ist nach dem [[Laaer]] Berg benannt, einer Erhebung im südöstlichen Teil Wiens. Das Gebiet war ursprünglich landwirtschaftlich geprägt, wurde aber im Laufe des 19. und 20. Jahrhunderts zunehmend urbanisiert und in das Stadtgebiet integriert"}, {"kategorie": "", "text": "Die Straße erstreckt sich über mehrere Kilometer und passiert dabei unterschiedliche Wohngebiete, Gewerbegebiete sowie Grünflächen. Sie ist eine der Hauptverbindungen im Bezirk und dient sowohl dem Durchgangsverkehr als auch der Erschließung der angrenzenden Viertel"}]'::jsonb, ''),
  ('liachtntoi', 'Liachtntoi', '', '', '', '', 'Lichtental', '[{"kategorie": "allg.", "text": "\"historisches Viertel im 9. Wiener Gemeindebezirk ([[Alsergrund]])\""}, {"kategorie": "", "text": "Lichtental liegt im südöstlichen Teil des 9. Bezirks, in der Nähe des [[Donaukanals]] und unweit des Wiener [[Gürtels]]. Das Viertel wird von den Straßen [[Liechtensteinstraße]], [[Nussdorfer]] Straße und [[Spittelauer]] Lände begrenzt"}, {"kategorie": "", "text": "Lichtental war bis 1850 eine eigenständige Gemeinde und entwickelte sich im 18. Jahrhundert als Vorstadt Wiens. Ursprünglich war es ein Ort, der von Handwerkern und einfachen Bürgern bewohnt wurde"}, {"kategorie": "", "text": "Das Viertel ist besonders bekannt für die [[Lichtentaler]] Pfarrkirche (Maria Geburt), die im Barockstil erbaut wurde und in der der berühmte Komponist Franz Schubert getauft wurde"}, {"kategorie": "", "text": "Franz Schubert, einer der bedeutendsten Komponisten der Wiener Klassik und Romantik, verbrachte in Lichtental seine Kindheit und Jugend, wurde in der Lichtentaler Pfarrkirche getauft und war dort später auch als Organist tätig"}, {"kategorie": "", "text": "Das Viertel ist durch eine gut erhaltene historische Bebauung geprägt, die größtenteils aus dem 18. und 19. Jahrhundert stammt. Die Architektur Lichtentals spiegelt seine Entwicklung von der Wiener Vorstadt zu einem integralen Bestandteil der urbanen Großstadt wider."}]'::jsonb, ''),
  ('altangrund', 'Altangrund', '', '', '', '', 'Althangrund', '[{"kategorie": "allg.", "text": "Stadtteil im nördlichen Teil des 9. Wiener Gemeindebezirks ([[Alsergrund]]), nahe dem [[Donaukanal]] und dem [[Franz-Josefs-Bahnhof]]"}, {"kategorie": "", "text": "Das Gebiet des Althangrundes war lange Zeit unbesiedelt. Die zum Gebiet gehörende [[Spittelau]] wurde jedoch bereits 1350 dem Bürgerspital zugesprochen, von der das Augebiet am Donaukanal seinen Namen erhielt. 1679 wurden hier sieben Baracken errichtet, um die Pestkranken von der Bevölkerung zu isolieren"}, {"kategorie": "", "text": "Der Name Althangrund geht wiederum auf Christoph Johann Graf Althan, „Obrist-Hofkuchelmeister und Obrist-Hof-Landjägermeister“ zurück, der den Bezirksteil 1690 erwarb. Ähnlich wie Fürst Liechtenstein im benachbarten [[Lichtental]] ließ Althan an der Als einen Garten sowie von Johann Bernhard Fischer von Erlach ein Lusthaus, das [[Palais]] Althan, errichten. 1706 starb Althan und vererbte seinen Besitz seinem Sohn Gundacker von Althan, der das Gebiet 1713 an das Wiener Magistrat verkaufte"}, {"kategorie": "", "text": "Das Gebiet ist durch eine Mischung aus Wohn-, Büro- und Universitätsgebäuden geprägt und hat eine bedeutende Rolle als urbanes Entwicklungsgebiet innerhalb Wiens"}]'::jsonb, ''),
  ('altanschdrossn', 'Altanschdrossn', '', '', '', '', 'Althanstraße', '[{"kategorie": "allg.", "text": "bedeutende Straße im 9. Wiener Gemeindebezirk ([[Alsergrund]]), die durch das Gebiet des [[Althangrunds]] verläuft"}, {"kategorie": "", "text": "Sie beginnt in der Nähe des [[Franz-Josefs-Bahnhofs]], einem wichtigen Verkehrsknotenpunkt im nördlichen Alsergrund, und erstreckt sich südlich in Richtung des Stadtzentrums"}, {"kategorie": "", "text": "Ihr Name geht auf Christoph Johann Graf Althan, „Obrist-Hofkuchelmeister und Obrist-Hof-Landjägermeister“ zurück, der den Bezirksteil 1690 erwarb. Ähnlich wie Fürst Liechtenstein im benachbarten [[Lichtental]] ließ Althan an der Als einen Garten sowie von Johann Bernhard Fischer von Erlach ein Lusthaus, das [[Palais]] Althan, errichten. 1706 starb Althan und vererbte seinen Besitz seinem Sohn Gundacker von Althan, der das Gebiet 1713 an das Wiener Magistrat verkaufte"}, {"kategorie": "", "text": "Historisch gesehen war die Althanstraße Teil des Expansionsgebiets Wiens im 19. Jahrhundert, als die Stadt ihre Grenzen erweiterte und neue Infrastrukturprojekte, wie den Bau des Franz-Josefs-Bahnhofs, umsetzte. Die Straße hat sich seitdem zu einer wichtigen Verkehrsader im Bezirk entwickelt und ist heute ein Zentrum für Bildung und städtische Entwicklung"}, {"kategorie": "", "text": "Heute führt die Althanstraße durch ein urbanes Gebiet, das eine Mischung aus Wohn-, Büro- und Bildungseinrichtungen beherbergt. Eine der markantesten Institutionen entlang der Althanstraße ist das Universitätszentrum Althanstraße, das früher als Standort der [[Wirtschaftsuniversität]] Wien diente und heute verschiedene Fakultäten der Universität Wien beheimatet."}]'::jsonb, ''),
  ('wu', 'WU', '', '', '', '', 'WU', '[{"kategorie": "wörtlich für", "text": "\"Wirtschaftsuniversität Wien\" =  \"größte wirtschaftswissenschaftliche Universität in Europa und eine der führenden Hochschulen weltweit im Bereich Wirtschaft und Management\""}, {"kategorie": "", "text": "Die WU befindet sich im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]), auf dem [[Messegelände]] in der Nähe des [[Praters]], und bietet ein breites Spektrum an Studiengängen und Forschungsprogrammen in den Wirtschafts-, Sozial- und Rechtswissenschaften"}, {"kategorie": "", "text": "Die Wirtschaftsuniversität Wien wurde 1898 als k.k. Exportakademie gegründet und hatte ursprünglich das Ziel, Fachkräfte für den Außenhandel auszubilden. Im Laufe der Jahre entwickelte sich die Institution weiter, wurde 1919 zur Hochschule für Welthandel umbenannt und erhielt schließlich 1975 ihren heutigen Namen Wirtschaftsuniversität Wien"}, {"kategorie": "", "text": "Seit 2013 befindet sich die WU auf einem modernen, architektonisch herausragenden Campus im 2. Bezirk, dem Campus WU. Der neue Campus wurde von international renommierten Architekten entworfen und umfasst mehrere Gebäude, darunter das ikonische Library & Learning Center (LC), das von Zaha Hadid Architects entworfen wurde. Der Campus bietet eine hochmoderne Infrastruktur mit Hörsälen, Bibliotheken, Lernräumen und sozialen Einrichtungen und ist so gestaltet, dass er interdisziplinäres Lernen und innovative Forschung unterstützt."}]'::jsonb, ''),
  ('goeoeteplotz', 'Gööteplotz', '', '', '', '', 'Goetheplatz', '[{"kategorie": "allg.", "text": "kleiner, aber bedeutender Platz im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), nahe der [[Albertina]] und der [[Wiener]] Staatsoper"}, {"kategorie": "", "text": "Der Goetheplatz ist nach dem großen deutschen Dichter Johann Wolfgang von Goethe benannt, und im Zentrum des Platzes steht ein imposantes Goethe-Denkmal. Dieses Denkmal wurde 1900 enthüllt und zeigt Goethe in einer sitzenden, nachdenklichen Pose, umgeben von allegorischen Figuren. Es ist eines der bekanntesten Denkmäler für Goethe außerhalb Deutschlands und zeugt von der tiefen Verehrung, die der Dichter auch in Österreich genießt"}, {"kategorie": "", "text": "Der Goetheplatz spielt eine wichtige Rolle im kulturellen Leben Wiens. Er ist ein Treffpunkt für Kunstliebhaber und Touristen, die die nahegelegene Albertina und die anderen kulturellen Institutionen der Umgebung besuchen. Der Platz bietet zudem eine kleine Oase inmitten der belebten Innenstadt, wo man sich kurz vom Trubel der Stadt erholen kann."}]'::jsonb, ''),
  ('sonnwendviatl', 'Sonnwendviatl', '', '', '', '', 'Sonnwendviertel', '[{"kategorie": "allg.", "text": "modernes, urbanes Stadtentwicklungsgebiet im 10. Wiener Gemeindebezirk ([[Favoriten]])"}, {"kategorie": "", "text": "Es liegt südlich des [[Hauptbahnhofs]] und erstreckt sich über ein Gebiet, das früher als Bahngelände genutzt wurde. Das Viertel ist eines der größten Stadtentwicklungsprojekte Wiens und steht für eine nachhaltige, zukunftsorientierte Stadtplanung"}, {"kategorie": "", "text": "Die Entwicklung des Sonnwendviertels begann in den frühen 2000er Jahren, als das Gelände des ehemaligen [[Südbahnhofs]] und der umliegenden Bahnanlagen im Zuge der Errichtung des neuen Wiener Hauptbahnhofs für eine urbane Nachnutzung freigegeben wurde. Das Stadtentwicklungsprojekt wurde von der Stadt Wien initiiert, um auf dem frei gewordenen Areal einen neuen, modernen Stadtteil zu schaffen"}, {"kategorie": "", "text": "Das Sonnwendviertel ist in mehrere Bereiche unterteilt, darunter das Sonnwendviertel Ost und das Sonnwendviertel West. Es umfasst eine Vielzahl von Wohnanlagen, die sowohl geförderten Wohnbau als auch frei finanzierte Wohnungen bieten. Die Architektur des Viertels ist modern und vielfältig, mit einem starken Fokus auf Nachhaltigkeit und Energieeffizienz"}, {"kategorie": "", "text": "Ein zentrales Element des Viertels ist der Helmut-Zilk-Park, eine großzügige Grünfläche, die als „grüne Lunge“ des Viertels dient und nach dem ehemaligen Wiener Bürgermeister [[Helmut]] Zilk benannt ist. Der Park bietet nicht nur Erholungsmöglichkeiten für die Bewohner, sondern trägt auch zur Verbesserung des Mikroklimas im Viertel bei."}]'::jsonb, ''),
  ('grossfoeoedsiidlung', 'Grossföödsiidlung', '', '', '', '', 'Großfeldsiedlung', '[{"kategorie": "allg.", "text": "einer der größten [[Gemeindebauten]] der Stadt im 21. Wiener Gemeindebezirk ([[Floridsdorf]])"}, {"kategorie": "", "text": "Der Bau der Großfeldsiedlung begann in den 1960er Jahren und dauerte bis in die frühen 1970er Jahre. Das Projekt entstand zu einer Zeit, als Wien dringend zusätzlichen Wohnraum benötigte, insbesondere in den Außenbezirken. Die Großfeldsiedlung wurde auf einem zuvor landwirtschaftlich genutzten Gebiet errichtet, das als Großfeld bekannt war, was der Siedlung ihren Namen gab"}, {"kategorie": "", "text": "Die Großfeldsiedlung besteht aus mehreren großen Wohnblöcken, die in einer charakteristischen, eher schlichten und funktionalen Architektur errichtet wurden. Die Gebäude sind meist zwischen acht und 16 Stockwerke hoch und bieten insgesamt mehr als 10.000 Wohneinheiten"}, {"kategorie": "", "text": "Die Großfeldsiedlung war von Anfang an als sozialer Wohnbau gedacht, um leistbaren Wohnraum für breite Bevölkerungsschichten zu schaffen. Die Siedlung bietet eine Vielzahl von sozialen Einrichtungen, darunter Schulen, Kindergärten, Einkaufszentren und Gesundheitseinrichtungen, sowie auch Grünflächen, Spielplätze und verkehrsberuhigten Zonen"}, {"kategorie": "", "text": "Die Siedlung hat im Laufe der Jahre eine diverse und multikulturelle Bewohnerschaft angezogen, was sie zu einem lebendigen und vielfältigen Stadtteil macht."}]'::jsonb, ''),
  ('hosnleitn', 'Hosnleitn', '', '', '', '', 'Hasenleiten', '[{"kategorie": "allg.", "text": "Stadtteil im 11. Wiener Gemeindebezirk ([[Simmering]]). Der Stadtteil ist bekannt für seine Wohnsiedlungen, insbesondere den sozialen Wohnbau, und spielt eine wichtige Rolle im städtischen Gefüge des Bezirks"}, {"kategorie": "", "text": "Der Name Hasenleiten leitet sich vermutlich von der historischen Nutzung des Gebiets ab, das ursprünglich ländlich geprägt war und möglicherweise als Jagdgebiet diente. Im Laufe der Zeit entwickelte sich Hasenleiten zu einem Wohngebiet, das insbesondere in der ersten Hälfte des 20. Jahrhunderts durch den Bau von [[Gemeindebauten]] geprägt wurde"}, {"kategorie": "", "text": "In den 1920er und 1930er Jahren, während der Ära des sogenannten à„Roten Wien“, wurden in Hasenleiten zahlreiche Wohnbauprojekte initiiert. Diese Projekte sollten leistbaren Wohnraum für Arbeiterfamilien schaffen und wurden nach den sozialen und hygienischen Standards dieser Zeit gestaltet"}, {"kategorie": "", "text": "Der Stadtteil ist heute ein lebendiges Wohngebiet, das durch seine soziale Durchmischung und die gute Anbindung an den öffentlichen Verkehr geprägt ist. Viele der Gemeindebauten sind bis heute bewohnt und bieten nach wie vor günstigen Wohnraum in einem Umfeld, das sowohl städtische Annehmlichkeiten als auch Grünflächen bietet."}]'::jsonb, ''),
  ('geislbeag', 'Geislbeag', '', '', '', '', 'Geiselberg', '[{"kategorie": "allg.", "text": "Gegend im 11. Wiener Gemeindebezirk ([[Simmering]]). Der Name bezieht sich sowohl auf einen Hügel als auch auf das umliegende Stadtviertel, das historisch und städtebaulich von Bedeutung ist"}, {"kategorie": "", "text": "Der Geiselberg und die umliegende Gegend waren ursprünglich landwirtschaftlich geprägt, bevor die Urbanisierung Wiens im 19. und frühen 20. Jahrhundert auch dieses Gebiet erreichte. Im Zuge der industriellen Entwicklung wurden in der Nähe des Geiselbergs Fabriken und Wohnsiedlungen errichtet, die zur Entstehung eines dicht besiedelten Stadtviertels führten"}, {"kategorie": "", "text": "Ein wichtiger Meilenstein in der Entwicklung des Geiselbergs war der Bau von Wohnanlagen, insbesondere während der Phase des sozialen Wohnbaus im à„Roten Wien“ der Zwischenkriegszeit. Diese Wohnanlagen sollten der arbeitenden Bevölkerung leistbaren Wohnraum bieten und trugen zur dichten Besiedelung des Gebiets bei"}, {"kategorie": "", "text": "Der Geiselberg ist heute gut an das Wiener öffentliche Verkehrsnetz angeschlossen. Die Gegend wird durch mehrere Straßenbahn- und Buslinien erschlossen, die eine schnelle Anbindung an das Wiener Stadtzentrum und andere Bezirke ermöglichen."}]'::jsonb, ''),
  ('lewabeag', 'Lewabeag', '', '', '', '', 'Leberberg', '[{"kategorie": "allg.", "text": "Stadtteil im 11. Wiener Gemeindebezirk ([[Simmering]]), der vor allem für seine großflächigen Wohnsiedlungen bekannt ist und sich in den letzten Jahrzehnten zu einem wichtigen Wohnviertel im Bezirk entwickelt hat"}, {"kategorie": "", "text": "Der Leberberg liegt im südöstlichen Teil von Simmering und grenzt an den [[Donaukanal]]. Das Gebiet erstreckt sich entlang der Ostbahn und umfasst mehrere Wohnsiedlungen, die in der zweiten Hälfte des 20. Jahrhunderts errichtet wurden. Die Gegend ist flach und zeichnet sich durch eine dichte Bebauung aus"}, {"kategorie": "", "text": "Der Leberberg war ursprünglich landwirtschaftlich genutzt und bestand größtenteils aus Feldern und Gärten. Mit dem Wachstum Wiens und der zunehmenden Urbanisierung im 20. Jahrhundert wurde das Gebiet nach und nach erschlossen und für den Wohnbau genutzt. Besonders in den 1970er und 1980er Jahren wurden hier zahlreiche Gemeindebauten und Wohnsiedlungen errichtet, die vor allem Familien und Menschen mit mittlerem Einkommen leistbaren Wohnraum bieten sollten"}, {"kategorie": "", "text": "Der Name Leberberg in Wien-Simmering leitet sich von der historischen Nutzung des Gebiets als landwirtschaftliche Fläche ab. Der Begriff \"Leber\" in diesem Zusammenhang hat nichts mit dem Organ zu tun, sondern stammt wahrscheinlich von einem alten Flurnamen oder einem ähnlichen Begriff ab, der sich im Laufe der Zeit etabliert hat."}]'::jsonb, '')
